    ('jiaban-tiaoxiu',
     '加班只给调休不给钱，合法吗？',
     '周末加班可以调休代替加班费，但法定节假日加班不行——那 3 倍工资必须真金白银给。',
     '劳动类', 'labor',
     '["调休", "加班费", "补休", "周末加班", "法定节假日", "换休"]',
     '国庆加了 3 天班，公司说「后面给你调休补回来」，钱一分没有。',
     '["休息日加班：单位可以安排补休，不能补休才付 2 倍工资", "法定节假日加班：只能付 3 倍工资，不能用调休替代", "工作日延长工时的，一律按 1.5 倍支付，没有调休一说", "保留加班审批、考勤和排班记录，作为主张加班费的依据"]',
     '["jiaban-fei", "gongzuo-shijian"]',
