    ('laodong-zhongcai',
     '劳动仲裁怎么申请？要花多久？',
     '劳动仲裁不收费，也不用先请律师——时效 1 年，立案后一般 45 天内出结果。',
     '劳动类', 'labor',
     '["劳动仲裁", "仲裁时效", "一年", "维权", "打官司", "免费", "仲裁流程"]',
     '被拖欠了两个月工资，想去告公司，又怕流程复杂、花钱多、耗时间。',
     '["记住时效：申请仲裁的时效是 1 年，从知道权利被侵害那天起算", "劳动关系存续期间因拖欠劳动报酬发生争议的，不受 1 年限制；离职的自离职之日起 1 年内提出", "向劳动合同履行地或公司所在地的仲裁委提交申请，仲裁不收费", "对裁决不服的，可在收到裁决书 15 日内向法院起诉"]',
     '["tuoqian-gongzi", "caiyuan-peichang"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('gongzuo-shijian',
     '996 合法吗？加班有上限吗？',
     '每天 8 小时、每周 44 小时是法定标准，加班每月最多 36 小时——996 直接超了一倍多。',
     '劳动类', 'labor',
     '["996", "工时", "加班上限", "36小时", "违法加班", "大小周", "强制加班"]',
     '公司推行「大小周 + 每天早十晚十」，不加班就影响考核，主管说「这是行业惯例」。',
     '["法定标准工时是每日不超过 8 小时、每周不超过 44 小时", "加班需与工会和劳动者协商，一般每日不超 1 小时，特殊原因每日不超 3 小时、每月不超 36 小时", "强制加班、超时加班可向劳动监察部门举报", "已发生的超时加班，仍应依法支付加班费"]',
     '["jiaban-fei", "jiaban-tiaoxiu"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('lisan-zhengming',
     '离职时公司不给离职证明，怎么办？',
     '离职证明是你的法定权利，公司扣着不给、不办社保转移，造成损失要赔。',
     '劳动类', 'labor',
     '["离职证明", "档案", "社保转移", "离职手续", "解除证明", "扣档案"]',
     '已经离职一个月了，新公司催着要离职证明，老东家说「你交接没做好，先不给你开」。',
     '["法律规定解除或终止合同时必须出具证明，并在 15 日内办理档案和社保转移", "先书面（邮件/微信留痕）催告公司限期出具", "仍不给的，向劳动行政部门投诉，责令改正", "因不出具证明导致你错过新工作等损失的，可要求公司赔偿"]',
     '["cizhi-chengxu", "nianjia-meixiu"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('guoqi-shipin',
     '买到过期食品，除了退款还能索赔吗？',
     '就像买到坏掉的水果不止要换一份——过期食品是法律给消费者的「加倍保护」：退款之外，还可以主张价款十倍的赔偿。',
     '消费类', 'consume',
     '["食品安全", "索赔", "维权", "过期食品", "变质", "吃坏肚子"]',
     '在便利店买了瓶酸奶，回家发现过期两天，店员说「退你钱就行了」。',
     '["保留小票、商品和包装（证据链第一环）", "先与商家协商：退货退款 + 主张赔偿", "协商不成，拨 12315 或在全国 12315 平台小程序投诉", "仍不解决，可向法院起诉（小额诉讼程序，成本低）"]',
     '["qitian-wuliyou", "xujia-xuanchuan"]',
     '2026-09-22', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('qitian-wuliyou',
     '网购收到货不满意，能七天无理由退吗？',
     '七天无理由退货像一段「试用期」——不喜欢可以退；但定做的、生鲜、拆封的软件等几类不在其列。',
     '消费类', 'consume',
     '["网购", "退货", "七天无理由", "退款", "退钱", "不想要了"]',
     '网上买了件外套，收到试穿发现颜色和图片差很多，想退货，客服说「已经拆封了不能退」。',
     '["从「收到商品之日」起算 7 日内提出退货，不需要说明理由", "确认不属于四类例外：定作、鲜活易腐、拆封的数字化商品、交付的报刊", "保持商品完好（吊牌、包装别丢），在平台正常申请退货退款", "运费一般由你承担，商家承诺包运费的从其约定；拒退可拨 12315 投诉"]',
     '["guoqi-shipin", "xujia-xuanchuan"]',
     '2026-10-02', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('yufuka-paolu',
     '办了年卡，店突然关门跑路了怎么办？',
     '预付卡里的钱不是「送」给商家的——他收了钱不提供服务，就得退给你，还得加上利息。',
     '消费类', 'consume',
     '["预付卡", "跑路", "退款", "健身房", "办卡", "退卡", "美容院", "理发店", "卡里还有钱"]',
     '在小区健身房办了 3000 元年卡，才去一个月，店门上贴着「内部装修」，然后再没开过。',
     '["先固定证据：办卡合同、付款凭证、剩余次数截图、店铺现状照片", "联系经营者要求继续履行或退回预付款；同时向商场、物业索要经营者信息", "拨 12315 或向市场监管部门投诉，多人一起投诉更容易被受理", "金额较大的可起诉；若收钱时就打算跑路，可能涉嫌诈骗，直接报警"]',
     '["qitian-wuliyou", "guoqi-shipin"]',
     '2026-10-06', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('xujia-xuanchuan',
     '商家宣传是假的，能要三倍赔偿吗？',
     '被商家的假话「骗」着买了东西，法律给的是三倍赔偿——算下来不足 500 元的，直接按 500 元赔。',
     '消费类', 'consume',
     '["虚假宣传", "欺诈", "三倍赔偿", "假货", "夸大", "货不对板"]',
     '直播间说「100% 纯羊绒」，买回来一检测全是化纤，找客服理论，对方只肯退货。',
     '["先留证：宣传页面截图或录屏、直播回放、聊天记录、商品实物", "要证明对方构成「欺诈」——故意告知虚假情况或隐瞒真相，让你做了错误决定", "主张三倍价款赔偿；增加赔偿不足 500 元的，按 500 元计算", "协商不成拨 12315 投诉，或起诉（小额诉讼程序成本低）"]',
     '["qitian-wuliyou", "yufuka-paolu"]',
     '2026-10-08', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published');

