     '["留证三件套：商品实物与包装、订单与支付记录、商家宣传页面截图", "要能证明商家「明知」——比如标称正品、承诺假一赔十、伪造授权", "主张退款并加三倍价款赔偿；增加赔偿不足 500 元的按 500 元计算", "协商不成拨 12315 投诉，或向法院起诉"]',
