     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('dingjin-yudingjin',
     '定金和订金，一字之差钱差一半',
     '定金是担保：你反悔拿不回，商家反悔要双倍还你；订金只是预付款，一般能退。',
     '消费类', 'consume',
     '["定金", "订金", "押金", "预付款", "双倍返还", "退定金"]',
     '订车时交了 5000 元，单据上写的是「订金」，后来不想买了，销售说「定金不退」。',
     '["先看清单据上写的是「定金」还是「订金」——法律效果完全不同", "定金数额不得超过主合同标的额的 20%，超过部分不产生定金效力", "商家违约的，你可以要求双倍返还定金；你违约的，无权要求返还", "写的是「订金/预付款」而商家拒退的，可直接主张返还，协商不成起诉"]',
     '["tuikuan-nan", "yufuka-paolu"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('sanbao-weixiu',
     '三包期内坏了，能退能换吗？',
     '三包不是「包修就算完」——修不好、修了又坏、超期没修好，都能要求退换。',
     '消费类', 'consume',
     '["三包", "维修", "保修", "退换货", "售后", "修不好"]',
     '手机买了两个月就开不了机，售后说「只修不退不换」，修了三次还是坏。',
     '["保留发票、三包凭证和每次维修记录（维修次数是关键证据）", "在保修期内先要求修理，注意让对方出具维修单据", "修理仍不能正常使用、或超过约定修理期限的，可要求更换或退货", "商家推诿的，向市场监管部门投诉或拨 12315"]',
     '["juzheng-zeren", "maijia-jiahuo"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('zengpin-zeren',
     '赠品坏了，商家要不要负责？',
     '「赠品不在保修范围」是商家自己的说法——促销送的赠品，商家要担和卖货一样的责任。',
     '消费类', 'consume',
     '["赠品", "赠品坏了", "促销", "保修", "免费送的", "买一送一"]',
     '买冰箱送的电饭煲用了两周就罢工，商家说「赠品不保修，坏了也没办法」。',
     '["保留促销页面、订单或小票，用来证明赠品是这次交易的一部分", "促销赠品属于「附义务的赠与」，商家要在赠与限度内承担与出卖人相同的责任", "赠品造成人身或财产损害的，另行主张侵权赔偿", "商家拒绝处理的，拨 12315 投诉"]',
     '["sanbao-weixiu", "bawang-tiaokuan"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('chichu-yiwu',
     '饭菜里吃出异物，能赔多少？',
     '吃出异物属于「不符合食品安全标准」——可以主张价款十倍赔偿，不足 1000 元按 1000 元算。',
     '消费类', 'consume',
