     '外卖里吃出一段塑料片，商家说「这单给你退了吧」，平台只补了 20 元红包。',
     '["立刻拍照、录视频，把异物和餐品原封保存，别急着扔掉", "留好订单、支付记录和与商家的聊天记录", "向商家索赔实际损失，并可主张价款十倍或损失三倍的赔偿金，不足 1000 元按 1000 元算", "商家推诿的，向市场监管部门投诉或起诉"]',
     '["guoqi-shipin", "tuikuan-nan"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('zhibo-daigou',
     '直播间买到假货，找谁赔？',
     '主播自己卖就找主播，平台内商家卖的就找商家；平台说不出商家真实信息，就得平台先赔。',
     '消费类', 'consume',
     '["直播带货", "主播", "直播间", "网红", "带货", "下单"]',
     '在主播的直播间下单买了「专柜同款」，收到发现做工粗糙，找主播被拉黑，找平台说「我们只是提供技术」。',
     '["截图或录屏直播回放、商品页和主播的口头承诺（这些都是证据）", "先分清主体：主播自己开店的找主播，平台内第三方商家的找商家", "平台无法提供商家真实名称、地址和有效联系方式的，可直接要求平台赔偿", "构成欺诈的，另可主张三倍价款赔偿"]',
     '["pingtai-zeren", "maijia-jiahuo"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('bawang-tiaokuan',
     '「最终解释权归本店」有效吗？',
     '这类「霸王条款」在法律上直接无效——不合理免除商家责任、限制你主要权利的，都不算数。',
     '消费类', 'consume',
     '["霸王条款", "格式条款", "最终解释权", "概不退换", "店堂告示", "概不负责"]',
     '办了张健身卡想退，前台指着墙上的告示说「本店保留最终解释权，一经售出概不退换」。',
     '["先认清常见无效条款：概不退换、最终解释权、财物丢失概不负责、最低消费", "把告示、合同或小票拍照留存，作为对方使用格式条款的证据", "书面（或在平台内）提出你的正当要求，明确不认可该条款", "商家坚持以该条款拒赔的，向市场监管部门投诉或起诉主张条款无效"]',
     '["zengpin-zeren", "xufei-koufei"]',
