VALUES
    ('jiage-qizha',
     '先涨价再打折，算欺诈吗？',
     '虚构原价、假折扣是典型的价格欺诈——它同时也是「欺诈行为」，可以主张三倍赔偿。',
     '消费类', 'consume',
     '["价格欺诈", "先涨后降", "假折扣", "虚假宣传", "双十一", "原价"]',
     '「双十一」前看好的商品，活动前悄悄从 199 改成 399，再挂出「五折优惠」，到手价其实和平时一样。',
     '["截图保存活动前后的价格页面和商品详情，能对比出「虚构原价」", "价格信息必须真实、全面，不得作虚假或引人误解的宣传", "构成欺诈的可主张三倍价款赔偿（不足 500 元按 500 元）", "向市场监管部门投诉，或拨 12315 举报价格违法行为"]',
     '["xujia-xuanchuan", "kanjia-weiyue"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('juzheng-zeren',
     '商品有瑕疵，谁来证明不是我的错？',
     '买电视、冰箱、电脑这类耐用商品，6 个月内出问题——举证责任在商家，不用你自证清白。',
     '消费类', 'consume',
     '["举证责任", "瑕疵", "质量问题", "耐用商品", "六个月", "自证清白"]',
     '新买的洗衣机用了三个月就漏水，商家说「你得证明是质量问题，不是你自己弄坏的」。',
     '["记住规则：机动车、计算机、电视、冰箱、空调、洗衣机等耐用商品，6 个月内出现瑕疵，由经营者举证", "保留购买凭证，明确告知商家「请依法承担举证责任」", "商品不符合质量要求的，可要求退货、更换、修理，运费由商家承担", "商家拒绝的，向市场监管部门投诉或起诉"]',
     '["sanbao-weixiu", "tuikuan-nan"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('peixun-tuifei',
     '培训班不想上了，学费能退吗？',
     '预交的学费不是「泼出去的水」——机构按约定提供服务，没提供就得退，还得付利息。',
     '消费类', 'consume',
     '["退费", "培训班", "教育机构", "学费", "课时", "不想上了"]',
     '交了两年 2 万元课程费，上了三个月发现老师全换了，想退剩下的钱，机构说「合同写了不退不换」。',
     '["先看合同退费条款，明显不合理免除机构责任的格式条款可以主张无效", "已上课时的费用按实际扣除，剩余部分属预付款，机构应按约定履行或退回", "退回预付款时还可主张利息和必要费用", "机构拒退的，向市场监管或教育主管部门投诉，必要时起诉"]',
     '["yufuka-paolu", "bawang-tiaokuan"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('chanpin-zeren',
     '电器爆炸伤人，该找店家还是厂家？',
     '产品缺陷致人损害，生产者和销售者都跑不掉——你可以挑一个索赔，他们之间再互相追偿。',
     '消费类', 'consume',
     '["产品责任", "电器爆炸", "缺陷产品", "厂家", "经销商", "伤人"]',
     '新买的电热水壶使用中炸裂，手被烫伤，找商家说「找厂家去」，厂家说「找卖你的人」。',
     '["先就医并保留病历、票据，同时封存产品残骸（关键物证）和购买凭证", "产品缺陷造成损害的，可向生产者索赔，也可向销售者索赔，任选其一", "明知缺陷仍然生产销售的，还可主张惩罚性赔偿", "对方推诿的，直接起诉生产者和销售者，由法院判明责任"]',
     '["renshang-peichang", "sanbao-weixiu"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('renshang-peichang',
     '在商场摔伤、餐厅烫伤，谁负责？',
     '经营者对消费场所负有安全保障义务——地滑没提示、椅子突然散架，都要赔。',
     '消费类', 'consume',
     '["摔伤", "烫伤", "安全保障", "商场", "餐厅", "人身伤害"]',
     '在超市门口因为地面积水没设警示牌滑倒，手腕骨折，超市说「是你自己没看路」。',
     '["先就医留好病历、票据，再回到现场拍照（地面状况、有无警示标志）", "尽量调取现场监控，或找目击者留下联系方式", "经营者未尽安全保障义务造成损害的，应承担赔偿责任", "协商不成的可起诉；对方有过错时可以减轻其责任，但不等于全免"]',
     '["chanpin-zeren", "chichu-yiwu"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('kanjia-weiyue',
     '秒杀抢到的订单，商家能砍单吗？',
     '下单成功合同就成立了——商家以「标错价」为由砍单，属于违约，要承担违约责任。',
     '消费类', 'consume',
     '["砍单", "秒杀", "标错价", "不发货", "订单取消", "违约"]',
     '凌晨抢到一台特价手机，付了款，第二天收到通知说「价格设置错误，订单取消」。',
     '["截图保存商品页面、价格、订单和支付记录（证明合同已成立）", "商家单方取消订单属违约，可要求继续履行（按订单发货）或赔偿损失", "若「标错价」是虚假宣传的幌子，可能还构成欺诈，可主张三倍赔偿", "协商不成向平台投诉、拨 12315，或起诉要求履行合同"]',
     '["jiage-qizha", "pingtai-zeren"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('pingtai-zeren',
     '网店跑路了，平台要赔吗？',
     '平台不是「只提供技术」就能免责——说不出卖家真实信息，或明知侵权不管，就得担责。',
     '消费类', 'consume',
     '["平台责任", "网店跑路", "电商平台", "卖家失联", "连带责任", "找谁赔"]',
     '在电商平台买的家具迟迟不发货，回头一看店铺已注销，平台客服说「我们只是交易场所」。',
     '["先向平台书面索要卖家的真实名称、地址和有效联系方式", "平台提供不出来的，可以直接要求平台赔偿", "平台明知或应知商家侵权却不采取措施的，与商家承担连带责任", "留好平台客服的答复记录，作为其「不能提供信息」的证据"]',
     '["zhibo-daigou", "tuikuan-nan"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('xufei-koufei',
     '会员自动续费，能退吗？',
     '「到期自动续费」得用显著方式提醒你——藏在小字里、不提醒就扣钱的，可以主张不算数。',
     '消费类', 'consume',
     '["自动续费", "会员", "会员卡", "扣费", "取消订阅", "免密支付", "乱扣钱"]',
     '视频会员试用期结束被自动扣了 258 元年费，翻遍 App 才在设置里找到取消入口。',
     '["先在 App 或支付平台关闭自动续费/免密支付，防止继续扣款", "截图保存当初的开通页面，看是否有醒目的续费提示", "格式条款未以合理方式提示的，可以主张该条款不成为合同内容", "已扣但未使用的部分可要求退还，协商不成向平台和市场监管投诉"]',
     '["bawang-tiaokuan", "peixun-tuifei"]',
