INSERT INTO cards
    (slug, title, summary, category, category_id, tags, scenario, solution_steps, related_slugs,
     published_at, updated_at, last_verified_at, author_type, reviewed_by, status)
VALUES
    ('pengyou-jietiao',
     '朋友借钱，借条到底怎么写才有用？',
     '借条就像游戏里的「存档点」——写对了，以后吵翻天也能读档重来；写错了，可能连吵架的资格都没有。',
     '借贷类', 'loan',
     '["借款", "借条", "欠条", "借钱不还", "利息", "朋友借钱"]',
     '好朋友急借 8000 元，说「咱俩这关系还要打借条？」你有点为难。',
     '["写清三要素：金额（大小写）、还款日期、双方姓名 + 身份证号", "利率别超过合同成立时一年期 LPR 的 4 倍，超出部分法律不保护", "转账交付，备注「借款」，别给现金", "到期不还，3 年内必须主张（诉讼时效）"]',
     '["zhiyou-zhuanzhang", "lixi-shangxian"]',
     '2026-09-22', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('zhiyou-zhuanzhang',
     '只有转账记录、没有借条，钱还能要回来吗？',
     '转账记录只能证明「钱动了」，证明不了「钱是借的」——所以转账时备注一句「借款」，比事后解释容易一百倍。',
     '借贷类', 'loan',
     '["转账记录", "微信转账", "没有借条", "聊天记录", "证据"]',
     '两年前微信转了 5 万给朋友，没写借条。现在他翻脸说「那明明是你还我的钱」。',
     '["先补聊天记录：他承认借钱、承诺还款，都能作为「借贷合意」的证据", "仅有转账凭证也能起诉，但对方一抗辩，举证责任又回到你身上", "优先用银行卡、微信转账（可追溯），避免现金交付", "诉讼时效 3 年，从约定还款日或你催告之日起算，别拖"]',
     '["pengyou-jietiao", "danbaoren"]',
     '2026-10-04', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('lixi-shangxian',
     '借条写了「月息 3 分」，这利息受保护吗？',
     '利息不是想写多少就多少——超过合同成立时一年期 LPR 四倍的部分，法院不会支持。',
     '借贷类', 'loan',
     '["利息", "高利贷", "月息", "利率", "LPR", "几分利"]',
     '急用钱时借了 10 万，借条写明月息 3 分（年化 36%），还了半年才发现利息高得离谱。',
     '["先算年化：月息 3 分 ≈ 年化 36%，大概率已超过 LPR 四倍这条线", "超过上限的部分不用还；已经付了的，可以主张冲抵本金或返还", "小心「砍头息」：利息预先从本金里扣的，按实际到手金额算本金", "留存借条、转账记录、还款凭证，向法院主张调整利息"]',
     '["pengyou-jietiao", "zhiyou-zhuanzhang"]',
     '2026-10-07', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('danbaoren',
     '给朋友做了借款担保，他不还钱我得还吗？',
     '担保不是签个名那么简单——没写清「连带责任」的，法律默认你只是一般保证人，债主要先去找借款人。',
     '借贷类', 'loan',
     '["担保", "保证人", "连带责任", "担保期限", "替人还钱"]',
     '朋友借钱让你当担保人，你在借条末尾签了「担保人：你的名字」。现在他联系不上，债主直接来找你。',
     '["先看担保类型：没写明或约定不明的，按「一般保证」处理，债主须先向借款人主张", "看保证期间：没有约定的只有 6 个月（从主债务履行期届满起算），过了就免责", "若被起诉，及时主张保证期间已过或先诉抗辩权", "签字前想清楚：担保就是替人还钱的承诺，别碍于情面"]',
     '["pengyou-jietiao", "zhiyou-zhuanzhang"]',
     '2026-10-09', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('kan-tou-xi',
     '借 1 万到手 8 千，砍头息能不认吗？',
     '借 10000 实际到账 8000，那 2000 是「砍头息」——法律明确禁止，本金按你实际拿到手的算。',
     '借贷类', 'loan',
     '["砍头息", "到账金额", "本金", "预扣利息", "借一万到手八千", "手续费先扣"]',
     '网贷平台说借 10000，先扣 2000「服务费」，实际到账 8000，但合同上写的还是借 10000、按 10000 算利息。',
     '["保存放款记录：银行/微信/支付宝到账截图，看清实际到账金额", "按实际到手金额算本金，只对 8000 承担还本付息义务", "要求对方出具结清明细，多还的部分主张返还", "协商不成可向当地金融监管部门投诉或起诉"]',
     '["lixi-shangxian", "wangdai-fuwufei", "pengyou-jietiao"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('cuishou-raoluan',
     '网贷逾期被电话轰炸、爆通讯录怎么办？',
     '催收只能找你本人、只能合理时段联系——骚扰亲友、群发通讯录、半夜打电话，都可以投诉举报。',
     '借贷类', 'loan',
     '["暴力催收", "爆通讯录", "电话轰炸", "催收骚扰", "网贷逾期", "骚扰家人"]',
     '逾期三天，催收电话从早打到晚，还把欠款信息群发给通讯录里的同事和亲戚，上班都待不下去。',
     '["开录音、存截图：来电号码、时间、聊天记录、群发记录都是证据", "向贷款平台官方客服投诉催收行为，要求停止骚扰第三人", "向中国互联网金融协会、当地 12345 或银保监部门举报", "正常债务仍要还：可与平台协商分期，别把「反催收」当成不还款"]',
     '["wangdai-fuwufei", "xinyongka-yuqi", "lixi-shangxian"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('huankuan-shunxu',
     '还的钱不够，先抵利息还是先抵本金？',
     '没特别约定时，法律规定先抵「实现债权的费用」、再抵利息、最后才是本金——还的部分先算利息。',
     '借贷类', 'loan',
     '["还款顺序", "先还利息", "先还本金", "部分还款", "抵充顺序"]',
     '欠 5 万本金加利息，这个月只能还 3000，对方说「这 3000 全是利息，本金一分没少」，到底谁说了算？',
     '["先看借款合同有没有约定抵充顺序，有约定从约定", "没约定时按法定顺序：实现债权的费用 → 利息 → 主债务（本金）", "每次还款都留凭证并写明「用于归还某笔借款」，避免说不清", "金额大或有争议时，让出借人出具还款确认，写清剩余本金"]',
     '["yuqi-lixi-fajin", "lixi-shangxian", "pengyou-jietiao"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('li-gun-li',
     '利滚利合法吗？利息算进本金再生息',
     '「利滚利」不是一律无效——前期利率不超标时，重新写的借条可以计入本金，但本息总和有天花板。',
     '借贷类', 'loan',
     '["利滚利", "复利", "利息转本金", "重新打借条", "以贷还贷"]',
     '借了 2 万还不上，对方要求「连本带息重写一张 3 万的借条」，一年后变成 5 万——这样滚下去合法吗？',
     '["核对前期利率有没有超过一年期 LPR 的四倍，超了就不能计入后期本金", "算总账：最终本息之和不得超过「以最初本金按四倍 LPR 算全部期间」的数额", "超过部分不用还，可要求按法定上限重新结算", "保留每张借条和转账记录，还原每一轮的本金和利率"]',
     '["lixi-shangxian", "yuqi-lixi-fajin", "kan-tou-xi"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published');

INSERT INTO cards
    (slug, title, summary, category, category_id, tags, scenario, solution_steps, related_slugs,
     published_at, updated_at, last_verified_at, author_type, reviewed_by, status)
VALUES
    ('yuqi-lixi-fajin',
     '逾期不还，利息和违约金能一起要吗？',
     '可以一起要，但两项加起来不能超过一年期 LPR 的四倍——超出的部分法院不支持。',
     '借贷类', 'loan',
     '["逾期利息", "违约金", "逾期还款", "罚息", "滞纳金"]',
     '借条写了「逾期一天罚 1%」，又约定了月息 2 分，逾期三个月对方把两项都算上，比本金涨得还快。',
     '["算清楚：逾期利息 + 违约金 + 其他费用，总额封顶为四倍 LPR", "超出封顶线的部分可以拒绝支付，法院也不会支持", "没约定逾期利率的，也可以按 LPR 主张逾期还款责任", "主动沟通并留下协商记录，争取减免或分期，比硬扛划算"]',
     '["lixi-shangxian", "li-gun-li", "huankuan-shunxu"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('fufu-gongzhai',
     '配偶欠的债，我必须一起还吗？',
     '共同签名的、或为家庭日常开销借的钱才是夫妻共同债务；一方瞒着借钱去赌去投资，原则上不用你还。',
     '借贷类', 'loan',
     '["夫妻共同债务", "共同还款", "配偶欠债", "一方借钱", "共签"]',
     '丈夫背着自己借了 30 万，钱没进家门，债主上门说「夫妻一体，你必须一起还」。',
     '["看有没有共同签名或事后追认——没有就先否定共同债务", "看钱的用途：家庭日常生活需要（房贷、学费、看病）才算共同债务", "超出日常开销的，由债权人举证证明钱用于共同生活或共同经营", "被起诉不要缺席，庭上把资金流向说清楚，必要时申请调取流水"]',
     '["lihun-fangchan", "yichan-zhaiwu", "duzhai-wuxiao"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('yichan-zhaiwu',
     '人走了，欠的钱要「父债子还」吗？',
     '继承人以遗产实际价值为限清偿债务——遗产 10 万、债 30 万，只还 10 万；不继承就不用还。',
     '借贷类', 'loan',
     '["父债子还", "遗产债务", "继承", "限定继承", "放弃继承"]',
     '父亲去世后留下 10 万存款和 30 万欠款，债主找到子女要求全额偿还，说不还就要起诉。',
     '["先理清遗产范围：存款、房产、车辆等，与自己的财产分开", "只在继承的遗产实际价值范围内清偿，超出的部分可以拒绝", "不想要遗产的，可以依法放弃继承，对债务可不负清偿责任", "对债务金额有异议的，要求债权人出示借条、转账凭证等证据"]',
     '["yichan-fenpei", "fufu-gongzhai", "pengyou-jietiao"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('duzhai-wuxiao',
     '赌债、赌球输的钱，法律管不管？',
     '赌博产生的「欠条」不受法律保护——违背公序良俗的债务无效，但参赌本身可能被治安处罚。',
     '借贷类', 'loan',
     '["赌债", "赌球", "不受保护的债", "公序良俗", "牌桌欠款"]',
     '打牌输了 2 万，被逼着写了欠条，现在对方拿欠条来要钱，还威胁去单位闹。',
     '["认清性质：赌博是违法行为，因此产生的债务不受法律保护", "不要续写借条、不要部分还款，避免被解释成「承认债务」", "被威胁、被骚扰的，保留证据并报警处理", "自己也涉赌的，主动接受处理比被对方拿捏更主动"]',
     '["cuishou-raoluan", "pengyou-jietiao", "fufu-gongzhai"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('wangdai-fuwufei',
     '网贷的「服务费」「担保费」能不算利息吗？',
     '换名头的费用也算进资金成本——利率超过一年期 LPR 四倍的部分，法律不保护。',
     '借贷类', 'loan',
     '["服务费", "担保费", "变相利息", "综合费率", "网贷费用", "砍头费"]',
     '借款页面写月利率 0.99%，实际放款时又收「服务费」「风险保障金」，七算八算比高利贷还高。',
     '["把所有费用加进资金成本，算出真实年化利率（别只看日息万几）", "对照合同成立时一年期 LPR 的四倍，超出部分可主张不付", "要求平台出具全部收费项目清单，保留合同和扣款记录", "被套路贷、被强迫交易的，及时报警"]',
     '["lixi-shangxian", "kan-tou-xi", "cuishou-raoluan"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('xinyongka-yuqi',
     '信用卡逾期了，会坐牢吗？该怎么办？',
     '一般欠款是民事纠纷不会坐牢；恶意透支、躲避催收才可能涉刑。主动协商比失联有效得多。',
     '借贷类', 'loan',
     '["信用卡逾期", "征信", "停息挂账", "协商还款", "信用卡起诉"]',
     '失业三个月，信用卡欠 4 万还不上，催收说「再不还就报警抓你」，吓得不敢接电话。',
     '["不要失联：主动联系银行说明情况，申请分期或个性化还款方案", "一般逾期属民事纠纷，不构成犯罪；以非法占有为目的恶意透支才可能涉刑", "按最低还款额先还一部分，表明还款意愿，减少违约后果", "警惕「代修复信」「反催收」中介，多为二次收费甚至诈骗"]',
     '["cuishou-raoluan", "wangdai-fuwufei", "yuqi-lixi-fajin"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('susong-shixiao',
     '借出去的钱，过三年就要不回来了吗？',
     '诉讼时效是三年，从「约定还款日」起算——期间催过款、对方认过账，时钟会重新走。',
     '借贷类', 'loan',
     '["诉讼时效", "三年", "过期不还", "时效中断", "欠款追讨"]',
     '2019 年借给同学 3 万没约定还款时间，一直不好意思催，现在想起诉，会不会已经过了时效？',
     '["没约定还款期限的，可以随时催告，时效从你催告的合理期限届满起算", "时效可以中断：微信催款、对方承诺还款、起诉都会让三年重新起算", "保留催款记录（聊天记录、通话录音），这是时效中断的关键证据", "快到期时让对方补一张还款承诺或还一部分钱，把时效续上"]',
     '["pengyou-jietiao", "zhiyou-zhuanzhang", "liaotian-jielu"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('qinqi-jieqian-lixi',
     '亲戚朋友借钱，好意思要利息吗？',
     '可以要，写明白就行；不写利息的，法律视为没有利息——人情归人情，约定归约定。',
     '借贷类', 'loan',
     '["亲友借款", "利息约定", "自然人借款", "无息借款", "借条利息"]',
     '表哥借 5 万周转，说「亲戚之间谈利息伤感情」，结果两年不还，自己又不好开口要。',
     '["想收利息就在借条里写清利率和还款时间，别只靠口头", "自然人之间没写利息的，视为没有利息，事后不能补着要", "利率写多少都行，但超过四倍 LPR 的部分不受保护", "到期不还先客气催告，留好聊天记录，为将来起诉固定证据"]',
     '["pengyou-jietiao", "lixi-shangxian", "susong-shixiao"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published');

