VALUES
    ('liaotian-jielu',
     '借条丢了，微信聊天记录能当证据吗？',
     '能。聊天记录、语音、转账记录都是证据，但要能对上「是谁、借多少、什么时候还」。',
     '借贷类', 'loan',
     '["借条丢了", "聊天记录", "电子证据", "微信记录", "没有借条"]',
     '借条被家里小孩撕了，只有微信里对方说「过两个月一定还」的记录，还能要回来吗？',
     '["保留原始载体：手机里的聊天记录别删，别只留截图", "补强信息：让对方在对话里确认借款金额、身份、还款时间", "转账记录 + 催款对话 + 对方认账的回复，三者拼起来就是完整证据链", "起诉时可以申请法院调取对方身份信息，电子证据可做公证保全"]',
     '["zhiyou-zhuanzhang", "pengyou-jietiao", "susong-shixiao"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('cuo-zhuan-zhang',
     '陌生人错转钱到我账户，不还会怎样？',
