     '["先别动这笔钱，联系银行说明情况并保留入账记录", "对方联系时核对身份和转账信息，配合原路退回", "对方拒不沟通或金额大的，让其走法律途径，自己不主动「处置」", "明知无合法依据仍花掉的，可能被起诉返还并赔偿损失"]',
     '["zhiyou-zhuanzhang", "cuishou-raoluan", "pengyou-jietiao"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('xieyi-huankuan',
     '欠钱还不上，怎么协商分期才靠谱？',
     '白纸黑字的还款协议有用：写清金额、期数、时间、违约责任，比口头「我一定还」管用。',
     '借贷类', 'loan',
     '["分期还款", "协商还款", "还款协议", "还不上钱", "展期"]',
     '生意亏了 8 万还不上，对方催得紧，想商量分期又怕对方之后不认账、直接起诉。',
     '["主动提出书面还款协议：本金、期数、每期金额、最后期限写清楚", "约定违约条款（如一期不还全部到期），给双方约束", "让家人或共同朋友做见证人，协议各留一份并签字按印", "按协议逐期履行并留凭证，别再出现「说好分期又全额起诉」"]',
     '["xinyongka-yuqi", "susong-shixiao", "pengyou-jietiao"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('liuyu-tiaokuan',
     '欠钱不还，写「房子直接归你」有效吗？',
     '这类「还不上东西就归你」的约定法律不认——抵押只能依法优先受偿，房子该拍卖拍卖、多退少补。',
     '借贷类', 'loan',
     '["流押条款", "抵押", "还不上房归你", "以物抵债", "优先受偿"]',
     '借 20 万时对方要求写下「到期还不上，我房子直接归你」并压了房本，现在逾期了，对方真要收房。',
     '["别慌：到期前约定的「直接归债权人所有」无效，只能就抵押财产优先受偿", "抵押应当办理登记（房产在不动产登记中心），没登记的抵押权不成立", "协商折价、拍卖、变卖都可以，价款优先还债后剩余部分要退还", "对方私自处分或威胁的，保留证据并尽快通过法院确认权利"]',
     '["danbaoren", "pengyou-jietiao", "yichan-zhaiwu"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('fangdong-bu-tui-yajin',
     '房东不退押金，一招制胜',
     '押金就像游戏里的「保证金」——只要你没损坏装备（房屋设施），通关（退租）时就得原样退还，少一分都可以较真。',
     '婚姻家庭类', 'marriage',
     '["押金", "租房", "退租", "房东不退", "二房东", "押一付三"]',
     '退租时房东以「墙面有钉子眼」为由，扣下 2000 元押金不还。',
     '["翻出租房合同，看押金条款怎么约定的", "正常使用痕迹（钉子眼、墙面自然老化）不属于「损坏」", "与房东书面协商，保留聊天记录", "可找社区调解、拨打 12345，或起诉（金额小，程序快）"]',
     '["lihun-fangchan", "yichan-fenpei"]',
     '2026-09-22', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('lihun-fangchan',
     '离婚了，房子和存款到底怎么分？',
     '婚后的工资、奖金、投资收益，法律默认是「两个人的」；婚前买的房、遗嘱里指定只给一方的除外。',
     '婚姻家庭类', 'marriage',
     '["离婚", "财产分割", "房子", "共同财产", "婚前房产", "分家产"]',
     '结婚 8 年，房子是婚后一起买的、贷款一起还的。现在要离婚，对方说「房产证写我名就是我的」。',
     '["先列财产清单：房产、存款、车辆、股权、公积金都算，分清婚前婚后", "婚后取得的工资奖金、生产经营投资收益属于夫妻共同财产，双方有平等处理权", "协商不成由法院判，会照顾子女、女方和无过错方权益", "对方隐藏、转移财产的，分割时可以少分或不分；离婚后发现的还能再起诉"]',
     '["caili-fanhuan", "fangdong-bu-tui-yajin"]',
     '2026-10-10', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('caili-fanhuan',
     '彩礼给了，婚没结成或刚结就离，能要回来吗？',
     '彩礼不是「买断费」——没办登记的、或办了登记却没真正一起生活的，法律支持返还；闪婚闪离 + 高额彩礼也会按比例退。',
     '婚姻家庭类', 'marriage',
     '["彩礼", "退彩礼", "结婚", "分手", "返还", "婚前给的钱"]',
     '按习俗给了 18 万彩礼，酒席办了但一直没领证，半年后两人分手，对方说「办过酒就是夫妻了，不退」。',
     '["先分清情形：未办登记、办了登记但未共同生活、婚前给付导致生活困难，都可以主张返还", "已登记且共同生活的，离婚时一般不支持返还；但「共同生活时间短 + 彩礼数额过高」法院会酌情按比例返还", "固定证据：转账记录、彩礼清单、媒人证言、共同生活的起止时间", "协商不成起诉；彩礼纠纷中，实际给付和接收彩礼的父母可以作为共同原告或被告"]',
     '["lihun-fangchan", "yichan-fenpei"]',
     '2026-10-11', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('yichan-fenpei',
     '父母去世没留遗嘱，遗产该怎么分？',
     '没遗嘱就按「法定继承」排队——配偶、子女、父母排第一顺序，同一顺序原则上平分。',
     '婚姻家庭类', 'marriage',
     '["遗产", "继承", "遗嘱", "父母去世", "分遗产", "法定继承"]',
     '父亲突然去世没留遗嘱，母亲还在，家里有两个子女，房子和存款不知道该怎么分。',
     '["先划清遗产范围：属于被继承人个人的财产才是遗产，配偶的一半要先析出", "第一顺序继承人是配偶、子女、父母；同一顺序原则上均等分配", "对生活有特殊困难、或尽了主要扶养义务的继承人，可以适当多分", "继承人之间先协商分配方案，谈不拢可以请求法院分割"]',
     '["caili-fanhuan", "lihun-fangchan"]',
     '2026-10-12', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published');

INSERT INTO cards
    (slug, title, summary, category, category_id, tags, scenario, solution_steps, related_slugs,
