VALUES
    ('jiabao-shenqing',
     '遭遇家暴，第一件事该做什么？',
     '先报警留记录，再申请人身安全保护令——出警记录、告诫书都是后续离婚和赔偿的关键证据。',
     '婚姻家庭类', 'marriage',
     '["家暴", "家庭暴力", "人身安全保护令", "报警", "告诫书", "被打"]',
     '被配偶殴打后不敢声张，想离婚又怕对方报复，也不知道报警会不会「家丑外扬」反而更糟。',
     '["第一时间拨打 110 并就医：出警记录、伤情照片、病历都要留好", "情节较轻的，公安机关可出具告诫书——它就是「家暴存在」的书面证据", "向法院申请人身安全保护令，72 小时内裁定，紧急的 24 小时内", "可向妇联、居委会求助或申请临时庇护；人身安全事件立即打 110"]',
     '["jiabao-lihun", "lihun-fangchan", "chugui-peichang"]',
