    ('jiabao-lihun',
     '被家暴起诉离婚，能一次判离吗？',
     '家暴是法定判离情形之一，还能同时主张离婚损害赔偿——但证据必须扎实。',
     '婚姻家庭类', 'marriage',
     '["家暴离婚", "起诉离婚", "判离", "离婚损害赔偿", "遭受殴打"]',
     '长期被打，第一次起诉离婚对方不同意，法院没判离，是不是永远离不掉？',
     '["家暴属于法定「调解无效应准予离婚」的情形，无需对方同意", "证据先行：报警回执、告诫书、伤情鉴定、照片录音、证人证言", "离婚时可一并主张损害赔偿（家暴是法定情形之一）", "第一次未判离的，分居满一年再起诉，法院应当准予离婚"]',
     '["jiabao-shenqing", "lihun-fangchan", "tanwangquan"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('lihun-lengjingqi',
     '离婚冷静期 30 天，到底怎么算？',
     '只对「协议离婚」生效：申请后 30 天内任何一方可撤回，期满后 30 天内要双方一起去领证。',
     '婚姻家庭类', 'marriage',
     '["离婚冷静期", "协议离婚", "撤回申请", "30天", "离婚证"]',
     '和配偶谈好了协议离婚，听说要「冷静 30 天」，担心这期间对方反悔，白跑一趟。',
     '["冷静期只适用于去民政局协议离婚，诉讼离婚没有冷静期", "提交申请后 30 天内任何一方可撤回；不想离的抓紧撤", "冷静期满后 30 天内，双方必须亲自到场申请发证，逾期视为撤回", "一方拖着不去领证的，另一方只能走诉讼离婚，不用再等冷静期"]',
     '["lihun-fangchan", "jiabao-lihun", "fenju-zidong-lihun"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('fenju-zidong-lihun',
     '「分居两年就自动离婚」是真的吗？',
     '假的。分居满二年只是法院判离的法定情形之一，离婚必须办登记或拿判决，不存在「自动离」。',
     '婚姻家庭类', 'marriage',
     '["分居两年", "自动离婚", "分居", "谣言", "起诉离婚"]',
     '两口子冷战分居快两年了，听朋友说「满两年自动就离了」，于是各自开始新的生活。',
     '["不存在自动离婚：不办登记、不拿判决，法律上仍是夫妻", "因感情不和分居满二年是判离情形之一，但要起诉并由法院认定", "分居证据要留：租房合同、居委会证明、聊天记录、证人证言", "「分居期间各自财产」仍可能是共同财产，别稀里糊涂处置"]',
     '["lihun-lengjingqi", "lihun-fangchan", "chugui-peichang"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('yanghaquan-guishu',
     '离婚后孩子判给谁？',
     '两岁以下原则上跟母亲；两到八岁看谁更有利孩子成长；八岁以上要听孩子自己的意愿。',
     '婚姻家庭类', 'marriage',
     '["抚养权", "孩子归谁", "判给谁", "离婚孩子", "争夺抚养权"]',
     '准备离婚，双方都想要孩子，又都担心「没工作的一方肯定抢不到」。',
     '["不满两周岁：以由母亲直接抚养为原则", "已满两周岁：协议不成由法院按最有利于未成年子女的原则判", "已满八周岁：应当尊重孩子真实意愿，法院会听取其意见", "没拿到抚养权不等于失去孩子，仍依法享有探望权并需付抚养费"]',
     '["fuzi-yanghafei", "tanwangquan", "lihun-fangchan"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('fuzi-yanghafei',
     '抚养费到底要给到孩子几岁？',
