     '婚姻家庭类', 'marriage',
     '["抚养费", "给多少", "抚养费标准", "月收入比例", "孩子开销"]',
     '离婚时约定每月给 800 抚养费，现在孩子上学 + 补课开销大了，能要求增加吗？',
     '["抚养费含生活费、教育费、医疗费，一般付至 18 周岁", "数额按不直接抚养方月收入 20%–30% 左右协商或由法院判", "原定数额不够的，孩子可以要求增加（上学、生病等大额支出）", "对方拒不支付的，可直接起诉，判决后可申请强制执行"]',
     '["yanghaquan-guishu", "tanwangquan", "shanyang-laoren"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('tanwangquan',
     '离婚后对方不让见孩子，怎么办？',
     '探望权是法定权利，可以起诉要求行使；但探望不利于孩子身心健康的，法院可以中止。',
     '婚姻家庭类', 'marriage',
