     '离婚后孩子跟着前妻，每次想看孩子都被各种理由拒绝，都快一年没见了。',
     '["探望的方式、时间先协商；协商不成可请求法院判决", "对方拒不配合的，可起诉主张探望权，判决后可申请强制执行", "行使探望权时别带孩子「藏起来」，那会反过来成为对方的把柄", "确有不利于孩子情形的（如暴力、酗酒），法院可中止探望，事由消失后恢复"]',
     '["yanghaquan-guishu", "fuzi-yanghafei", "jiabao-lihun"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('chugui-peichang',
     '对方出轨，我能多分财产要赔偿吗？',
     '单纯的出轨不必然多分财产，但「重婚」「与他人同居」等重大过错，无过错方可以主张离婚损害赔偿。',
     '婚姻家庭类', 'marriage',
     '["出轨", "离婚赔偿", "净身出户", "重大过错", "捉奸"]',
     '发现配偶和第三者长期同居，气得想让他「净身出户」，又不知道法律上站不站得住。',
     '["「净身出户」没有法律强制力，财产分割仍按法律规定和约定", "重婚、与他人同居等重大过错，无过错方可主张离婚损害赔偿", "证据要合法取得：聊天记录、转账、开房记录可作线索，别去偷拍他人住宅", "对方转移财产的，分割时可以少分或不分（见隐藏转移财产卡）"]',
