     '["婚前全款买的房、登记在自己名下：属于个人财产，不参与分割", "婚后共同还贷部分及对应增值，产权方应对另一方补偿", "婚后一方父母出资购房另有约定的，按约定处理", "拿不准的，把出资凭证、贷款记录、房产证登记时间都整理好"]',
     '["lihun-fangchan", "fufu-caichan-xieyi", "chugui-peichang"]',
