    ('fangchan-jiaming',
     '房产证上加了对方名字，房子就有一半了吗？',
     '加名在法律上等于把个人房产的一部分赠与对方，房子从个人财产变成共同财产；但「有一半」不等于「一定对半分」。',
     '婚姻家庭类', 'marriage',
     '["房产加名", "加名", "房产证", "不动产权证", "赠与", "共同财产", "过户"]',
     '婚前自己买的房，结婚时女方要求在房产证上加名字，加了就真的一半了吗？',
     '["先弄清加名的性质：在不动产权证上加名，本质是产权人把份额赠与对方，要办登记才生效", "只口头答应、或签了协议但还没过户的，赠与在登记前可以撤销，别以为签了字就稳了", "加名后房屋一般变为夫妻共同财产，但「共同共有」不等于「一人一半」——分割时法院会综合看出资来源、结婚年限、子女抚养等情况判定", "想事先把份额说清楚的，可以书面约定按份共有，并写进不动产登记簿"]',
     '["hunqian-caichan", "lihun-fangchan", "fufu-caichan-xieyi"]',
     '2026-10-21', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('fufu-caichan-xieyi',
     '婚后想「AA 制」，写协议有用吗？',
