     '["约定必须采用书面形式，口头说不算", "可以约定婚前财产、婚后所得各自所有或部分共同", "约定对外也有约束力，但对方知道该约定的，才以其个人财产清偿", "涉及房贷、共同生活的开支，建议一并写明分担方式"]',
