     '["赡养义务是法定的，不以「分家不公」为由免除", "先找居委会、村委会或人民调解组织调解，成本低", "调解不成可直接起诉，缺乏劳动能力或生活困难的老人都有权主张", "老人再婚的，子女赡养义务不变，不得因此断绝往来"]',
