     '["遗嘱", "自书遗嘱", "打印遗嘱", "见证人", "遗嘱无效"]',
     '老人想立遗嘱把房子留给一直照顾自己的小儿子，自己写了半天，怕格式不对以后被法院认定无效。',
     '["自书遗嘱：全文亲笔书写、签名、注明年月日，缺一不可", "打印遗嘱：两个以上见证人在场，遗嘱人和见证人在每一页签名注明年月日", "录音录像遗嘱：同样要两个以上见证人，并记录姓名或肖像和年月日", "更稳妥的做法是到公证处办公证遗嘱，或请律师见证"]',
     '["fading-jicheng-shunxu", "yichan-fenpei", "yichan-zhaiwu"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('fading-jicheng-shunxu',
     '没留遗嘱，遗产按什么顺序分？',
     '第一顺序是配偶、子女、父母，第二顺序是兄弟姐妹、祖父母、外祖父母——同一顺序一般均等分。',
     '婚姻家庭类', 'marriage',
     '["法定继承", "继承顺序", "遗产分配", "没立遗嘱", "第一顺序"]',
     '父亲突然去世没留遗嘱，家里有母亲、两个子女和爷爷，房产和存款到底怎么分？',
     '["先分清夫妻共同财产：一半归配偶，另一半才是遗产", "有第一顺序继承人（配偶、子女、父母）的，第二顺序不参与", "同一顺序一般均等，但尽了主要扶养义务或共同生活的可以多分", "有遗嘱的按遗嘱办理，有遗赠扶养协议的优先按协议"]',
     '["yizhu-zenme-xie", "yichan-fenpei", "zaihun-jicheng"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('zaihun-jicheng',
     '老人再婚，子女有权反对老伴继承吗？',
     '再婚配偶是第一顺序继承人，子女不得干涉老人再婚，也不能以此拒付赡养费。',
