     '["再婚", "老年再婚", "继承权", "干涉婚姻", "后老伴"]',
     '七十岁的父亲想再婚，子女担心「房子会被后妈分走」，逼父亲签协议放弃继承权。',
     '["老人再婚自由，子女不得干涉，也不得以此终止赡养义务", "再婚配偶与子女同为第一顺序继承人，份额一般均等", "想按自己意愿分配的，立一份有效遗嘱最直接", "婚前财产约定 + 遗嘱双管齐下，能避免身后纠纷"]',
