VALUES
    ('feihunsheng-zinv',
     '非婚生子女，有权继承遗产吗？',
     '有。非婚生子女与婚生子女权利完全平等，生父生母都要负担抚养费，也都有继承权。',
     '婚姻家庭类', 'marriage',
     '["非婚生子女", "私生子", "继承权", "抚养费", "亲子鉴定"]',
     '孩子出生时父母没领证，现在生父去世，其他亲属说「没结婚的孩子没资格分遗产」。',
     '["非婚生子女享有与婚生子女同等的权利，任何组织或个人不得歧视", "不直接抚养的一方必须负担抚养费，直至子女成年", "继承时与婚生子女同属第一顺序，份额一般均等", "对方不认孩子的，可做亲子鉴定后主张抚养费与继承权"]',
     '["fuzi-yanghafei", "fading-jicheng-shunxu", "yanghaquan-guishu"]',
