    ('dianche-pengzhuang',
     '下班路上被电动车撞了，第一步做什么？',
     '别急着私了也别急着吵——就像手机屏幕碎了先截图，路上出事故第一件事是「固定证据」，其次才是谈责任。',
     '交通类', 'traffic',
     '["电动车", "撞人", "被撞", "交通事故", "逆行", "非机动车"]',
     '晚高峰骑车下班，被一辆逆行电动车撞倒，对方说「给你 200 块私了吧」。',
     '["先确认人身安全，受伤立即拨打 120", "报警 122，等交警出具《道路交通事故认定书》", "拍现场照片：车辆位置、刹车痕、周边监控位置", "私了有风险：伤情后发（如脑震荡）将无处追偿"]',
     '["shigu-peichang", "jiuche-zheren"]',
     '2026-09-22', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('jiuche-zheren',
     '把车借给朋友开，出了事故车主担责吗？',
     '车借出去，责任跟着「开车的人」走——只有你明知车有毛病、或明知对方无证、喝了酒还借，才要担责。',
     '交通类', 'traffic',
     '["借车", "车主责任", "出借车辆", "连带", "事故"]',
     '朋友借你的车去接人，路上追尾了。伤者家属找上门，说「车是你的，你就得赔」。',
     '["赔偿有顺序：先交强险，不足部分商业险按合同赔，仍不足才由侵权人赔", "原则上由实际使用人（借车人）承担赔偿责任，车主没有过错就不赔", "但明知对方无证、酒后开车，或明知车辆有缺陷仍出借的，车主按过错承担相应责任", "出借前确认对方有证、没喝酒、车况正常，并留存沟通记录"]',
     '["dianche-pengzhuang", "shigu-peichang"]',
     '2026-10-01', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('shigu-peichang',
     '出了车祸，到底能要求赔哪些钱？',
     '医药费只是第一项——误工费、护理费、营养费，伤残了还有残疾赔偿金，法律列了一张清单。',
     '交通类', 'traffic',
     '["车祸", "赔偿", "误工费", "伤残", "医疗费", "事故赔偿"]',
     '骑车被撞骨折，住院 20 天，回家休养 3 个月。对方保险只肯赔医药费，别的都说「没有」。',
     '["保留全部票据：医疗费、护理费、交通费、营养费、住院伙食补助费", "开好误工证明（单位盖章 + 工资流水），主张因误工减少的收入", "构成伤残的做伤残鉴定，再主张辅助器具费和残疾赔偿金", "赔偿顺序：交强险 → 商业三者险 → 侵权人自己承担"]',
     '["dianche-pengzhuang", "jiuche-zheren"]',
     '2026-10-04', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('jiujia-tongzhuo',
     '朋友喝酒后开车出事，一起喝酒的要担责吗？',
     '劝酒、灌酒、明知他要开车还不拦——这几类「没管住嘴和手」的情形，法院很可能认定你也有过错。',
     '交通类', 'traffic',
     '["酒驾", "同桌", "劝酒", "共同饮酒", "担责", "醉驾"]',
     '聚餐时大家轮流劝酒，散场时他坚持自己开车回，你劝了两句就没再管，结果他路上撞了人。',
     '["同饮人对彼此负有一定的安全注意义务：不劝酒、不灌酒、不让他酒后开车", "明知对方要开车仍劝酒，或明知其已醉酒却不劝阻、不安排安全送返，可能被认定有过错", "有过错的，要按过错程度承担相应的赔偿责任", "最稳妥：叫代驾、留宿或通知家属，并保留劝阻的聊天记录"]',
     '["dianche-pengzhuang", "shigu-peichang"]',
     '2026-10-06', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('jiujia-chengke',
     '喝了酒开车，代价到底有多大？',
     '酒驾暂扣驾照六个月 + 罚款；醉驾吊销驾照、追究刑事责任、五年内不能重考——没有「就开一小段」。',
     '交通类', 'traffic',
     '["酒驾", "醉驾", "喝酒开车", "吊销驾照", "危险驾驶", "酒后代驾"]',
     '聚餐喝了两杯啤酒，想着「就两公里，慢慢开回去」，被查到了才知道后果。',
     '["喝酒不开车：代驾、打车、找人接，成本远低于后果", "酒驾（血液酒精 ≥20mg/100ml）：暂扣驾照六个月 + 1000–2000 元罚款", "醉驾（≥80mg/100ml）：吊销驾照、依法追究刑事责任、五年内不得重考", "酒驾醉驾出事故，商业险通常拒赔，交强险垫付后还会追偿"]',
     '["jiujia-tongzhuo", "dianche-pengzhuang", "shigu-taoyi"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('chuhongdeng-bei-zhuang',
     '我闯红灯被车撞了，司机要全赔吗？',
     '不是。机动车没过错也要担责，但最多不超过 10%；自己有错的，按过错程度减轻司机责任。',
     '交通类', 'traffic',
     '["闯红灯", "行人被撞", "责任划分", "机动车无过错", "过马路"]',
     '赶时间闯了红灯被正常行驶的车撞伤，司机说「你自己闯红灯，我一分不赔」，对吗？',
     '["报警并等交警出《交通事故认定书》，它是划分责任的核心证据", "机动车与行人事故：行人无过错由机动车全赔；行人有过错适当减轻；机动车无过错也担责不超过 10%", "行人故意碰撞（碰瓷）造成的损失，机动车不担责", "赔偿先走交强险，不足部分按责任比例承担"]',
     '["dianche-pengzhuang", "shigu-peichang", "renshang-xiangmu"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('chemai-weiguohu',
     '车卖了没过户，出了事故我担责吗？',
     '已经交付但没过户的，责任由买方（受让人）承担，原车主不再赔——但要能证明车确实交出去了。',
     '交通类', 'traffic',
     '["卖车不过户", "过户", "二手车", "车主责任", "车辆转让"]',
     '半年前把车卖了，对方一直拖着没去过户，现在听说那车出了事故，怕自己被起诉。',
     '["已经转让并交付的，事故责任由受让人承担，与原车主无关", "保留证据：买卖合同、付款记录、交车凭证、保险转移记录", "尽快催对方办理过户，避免自己名义下的违章和事故风险", "联系不上的，可以凭合同向法院起诉要求配合过户"]',
     '["jiuche-zheren", "guakao-shigu", "tou-kaiche"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published');

