     '["法律明确：挂靠经营的机动车出事故，挂靠人和被挂靠人连带赔偿", "受害方可以任选一方主张全部赔偿，两方内部再按约定分担", "查看挂靠协议的责任分担条款，先行赔付后再内部追偿", "挂靠协议最好写清保险投保义务和事故分担比例"]',
