     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('dingjie-bufu',
     '不认交通事故认定书，还能翻案吗？',
     '认定书是证据不是终局裁决——可以申请复核，也可以在民事诉讼中用其他证据推翻。',
     '交通类', 'traffic',
     '["责任认定", "复核", "不服认定书", "交通事故认定", "全责"]',
