    ('wangyueche-chengke',
     '网约车出事故，乘客找谁赔？',
     '先走保险，再按责任找司机/平台——营运车辆出事故，平台作为承运人也有责任。',
     '交通类', 'traffic',
     '["网约车事故", "乘客受伤", "平台责任", "承运人", "打车受伤"]',
