VALUES
    ('wu-baoxian-shigu',
     '对方没保险或保险不够赔，怎么办？',
     '先交强险、再商业险、最后侵权人自掏腰包；没投保交强险的，投保义务人在限额内先赔。',
     '交通类', 'traffic',
