     '["赔偿顺序：交强险限额内全额赔 → 商业险按合同赔 → 剩余由责任人承担", "对方没投保交强险的，可要求投保义务人在交强险限额内先赔", "申请财产保全（查封对方车辆、账户），防止判了也拿不到钱", "分期履行、执行和解都是拿钱的路，别轻易签「一次性了结低价协议」"]',
