    ('gou-bu-shuansheng',
     '遛狗不拴绳咬了人，狗主人全赔吗？',
     '基本要全赔——违反规定未拴绳等未采取安全措施致害的，只有被咬人「故意」才能减轻责任。',
     '邻里 / 名誉类', 'neighbor',
     '["遛狗不拴绳", "被狗咬", "狗主人责任", "狂犬疫苗", "宠物伤人"]',
     '小区里有只大型犬从不拴绳，今天扑倒了孩子，狗主人说「我家狗不咬人，是你孩子先跑」。',
     '["立即就医并打狂犬疫苗，保留病历、票据和伤口照片", "报警或找物业固定证据：狗主信息、现场目击者、监控", "未拴绳属未采取安全措施，狗主人几乎无法免责，只能证明「你故意」才减轻", "赔偿谈不拢可起诉，医疗费、误工费、精神损害都可主张"]',
     '["gou-bu-shuansheng", "chongwu-raomin", "jingshen-sunhai"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('chongwu-raomin',
     '邻居家狗半夜狂叫，投诉有用吗？',
     '有用。饲养动物干扰他人生活，先警告后处罚；保留录音和投诉记录是关键。',
     '邻里 / 名誉类', 'neighbor',
     '["狗叫扰民", "宠物扰民", "投诉邻居", "饲养动物", "警告处罚"]',
     '邻居家养了三只狗，主人白天上班关在屋里，狗从早叫到晚，多次沟通都被怼回来。',
     '["录音留证：记录狗叫的时间段和分贝，连续多天更有说服力", "先向物业、居委会投诉并要求书面调解", "调解不改的可报警，警方可先警告，不改正的可罚款", "长期扰民影响生活的，可起诉要求排除妨碍"]',
     '["gou-bu-shuansheng", "yantaom-zaoyin", "chongwu-raomin"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('qunli-ruzhu',
     '被人在业主群指着鼻子骂，怎么办？',
     '群里公开辱骂也是名誉侵权——要求道歉、删除，严重的可以报警或起诉赔偿。',
     '邻里 / 名誉类', 'neighbor',
     '["业主群辱骂", "微信群骂人", "名誉侵权", "公开羞辱", "道歉"]',
     '因为停车问题被邻居在 500 人的业主群里用难听话骂了三天，还把我的门牌号发出来了。',
     '["截图并公证：群名、时间、发言内容、群成员规模都是证据", "先要求对方删除并公开道歉，可请物业或群主介入", "公然侮辱他人的可报警，警方可处拘留或罚款", "影响较大的可起诉：停止侵害、恢复名誉、赔礼道歉、赔偿损失"]',
     '["wangluo-zaoyao", "paizhao-chuanbo", "mingyu-gongshi"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('mingyu-gongshi',
     '公司群里被同事造谣「吃回扣」，能告吗？',
     '能。捏造事实诽谤他人侵害名誉权，可要求停止侵害、赔礼道歉并赔偿；情节重的还可能被治安处罚。',
     '邻里 / 名誉类', 'neighbor',
     '["职场造谣", "诽谤", "吃回扣", "同事关系", "名誉赔偿"]',
     '同事因为竞争岗位，在工作群里发「他拿供应商回扣才升的职」，全公司都看到了。',
     '["固定证据：聊天记录、邮件、转发范围，必要时公证", "先书面要求其删除并澄清，抄送 HR 或领导", "公司不处理的，可以报警（公然侮辱/诽谤）或起诉名誉侵权", "主张赔偿时列出实际损失：绩效、晋升、精神损害"]',
     '["qunli-ruzhu", "wangluo-zaoyao", "paizhao-chuanbo"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('yaoyan-pianju',
     '在群里说「小区有人贩子」，被拘留冤吗？',
     '没有依据就散布「偷孩子」「抢人」这类消息，属于散布谣言扰乱公共秩序，可被拘留罚款。',
     '邻里 / 名誉类', 'neighbor',
     '["散布谣言", "贩子谣言", "业主群转发", "治安处罚", "未经证实"]',
     '看到邻群有人说小区来了偷小孩的，随手转发到业主群提醒大家，第二天却被叫去派出所。',
     '["转发未经证实的信息也可能构成散布谣言，先核实再传播", "已转发的尽快在原群澄清并删除，说明来源不实", "配合调查、认错态度好的一般从轻处理", "提醒家人：涉及安全事件请以官方通报为准，报警核实最稳妥"]',
     '["wangluo-zaoyao", "qunli-ruzhu", "mingyu-gongshi"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('paizhao-chuanbo',
     '被偷拍还发到网上，怎么让他删掉？',
     '偷拍偷窥散布他人隐私可拘留；同时可民事起诉，要求删除、道歉并赔偿。',
     '邻里 / 名誉类', 'neighbor',
     '["偷拍", "隐私权", "照片被发", "网暴", "删除视频"]',
     '在小区健身房被邻居偷拍身材视频，还配了调侃文字发到短视频平台，播放量好几万。',
     '["截图保存视频、账号信息、评论转发数据（可做公证）", "向平台投诉要求下架，并留存平台处理记录", "报警：偷窥、偷拍、散布他人隐私可处拘留或罚款", "起诉主张：停止侵害、赔礼道歉、精神损害赔偿"]',
     '["qunli-ruzhu", "wangluo-zaoyao", "jingshen-sunhai"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('gao-kong-pao-wu-zeren',
     '楼上扔东西砸了人，找不到是谁怎么办？',
     '高空抛物先由侵权人担责；查不出具体是谁的，可能加害的建筑物使用人要给予补偿。',
     '邻里 / 名誉类', 'neighbor',
     '["高空抛物", "坠物", "整栋楼补偿", "物业责任", "找不到人"]',
     '被楼上掉下来的花盆砸伤头部，报警后查监控也没拍到具体哪户，难道只能自认倒霉？',
     '["立即报警并就医，警方有职责依法及时调查查清责任人", "查不清的，除能自证清白的，可能加害的住户要给予补偿", "补偿后如果找到真正的侵权人，先行补偿的人可向他追偿", "物业未采取必要安全保障措施的，也要承担相应责任"]',
     '["gao-kong-pao-wu-zeren", "jingshen-sunhai", "loudong-loushui"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('menshi-sheixiangtou',
     '邻居在我家门口装摄像头，能要求拆除吗？',
     '门口虽是公共区域，但进出信息属于隐私——拍到邻居家门口、记录日常出入的，可以要求调整或拆除。',
     '邻里 / 名誉类', 'neighbor',
     '["门口摄像头", "监控", "隐私权", "对门安装", "进出记录"]',
     '对门在我家正对面装了个摄像头，画面正对我家门口，家里谁几点出门都被看得一清二楚。',
     '["先协商：说明拍摄范围覆盖自家门口，请求调整角度或拆除", "协商不成请物业、居委会书面调解，留好记录", "拍到的内容如果被传播或用于威胁，直接报警", "可起诉请求停止侵害、拆除或调整设备并删除影像"]',
     '["paizhao-chuanbo", "loudong-loushui", "qunli-ruzhu"]',
     '2026-10-16', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published');

INSERT INTO cards
    (slug, title, summary, category, category_id, tags, scenario, solution_steps, related_slugs,
     published_at, updated_at, last_verified_at, author_type, reviewed_by, status)
VALUES
    ('loudong-chaozhu',
     '楼上装修吵翻天，除了忍还能怎么办？',
     '楼层之间就像共享一张桌子——你有敲桌子的自由，但不能在别人睡觉时敲。噪音权是有边界的，越界就要管。',
     '邻里 / 名誉类', 'neighbor',
     '["噪音", "扰民", "装修", "楼上吵", "隔音"]',
     '楼上连续两周早上 7 点开始电钻装修，沟通后对方说「我装修我自由」。',
     '["先查当地装修时间规定（多数城市：工作日 8:00–12:00、14:00–18:00）", "记录噪音时间并录音录像，形成证据", "找物业出面协调（装修一般有保证金约束）", "仍无效可报警，或依据《噪声污染防治法》向城管等部门投诉"]',
     '["gao-kong-pao-wu-zeren", "gou-bu-shuansheng"]',
     '2026-09-22', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('wangluo-zaoyao',
     '在网上被人造谣辱骂，怎么维权？',
     '网络不是法外之地——先固定证据，再通知平台删帖；平台接到通知不处理，要对扩大的损失担连带责任。',
     '邻里 / 名誉类', 'neighbor',
     '["造谣", "诽谤", "名誉", "网络暴力", "骂人", "维权"]',
     '有匿名账号在社交平台发帖造谣你「欠钱不还」，还配了你的照片，评论区一堆人跟着骂。',
     '["第一步固定证据：录屏 + 截图（含账号、发布时间、阅读量、评论区）", "书面通知平台删除、屏蔽、断开链接；通知要包含侵权初步证据和你的真实身份信息", "平台接到通知未及时采取必要措施的，对损害的扩大部分与发帖人承担连带责任", "同时可以起诉，要求停止侵害、赔礼道歉、消除影响、赔偿损失"]',
     '["gao-kong-pao-wu-zeren", "loudong-chaozhu"]',
     '2026-10-07', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('zhuangxiu-hetong',
     '装修合同怎么签才不吃亏？',
     '装修像请人给你家做手术——术前把用哪家的材料、切多深都写清楚，术后才不用听他说「这都是正常现象」。',
     '邻里 / 名誉类', 'neighbor',
     '["装修合同", "装修", "半包", "全包", "增项", "装修公司跑路", "工期拖延", "验收"]',
     '找装修公司签合同，报价单只有一句「水电改造按实际发生计算」，施工后又冒出一堆增项，总价翻了一半。',
     '["报价单必须逐项写清品牌型号、数量、单价、工艺，别接受「按实际发生」这种开口条款", "合同写明开工与竣工日期、逾期违约金标准，以及增项须经你书面同意才生效", "付款按施工节点分次支付，留 5%~10% 尾款到验收合格后再付", "保留报价单、聊天记录、现场照片视频；出现严重质量问题时先书面通知整改，不改可主张修理、返工或赔偿"]',
     '["loudong-chaozhu", "chai-chengzhongqiang", "renshang-peichang"]',
     '2026-10-26', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published'),

    ('shenfenzheng-bei-maoyong',
     '身份证丢了被人拿去用，我要担责吗？',
     '身份证像家里的钥匙——钥匙被偷配了一把去开门，不该由你赔；但发现丢了要赶紧挂失补办，别当没发生。',
     '借贷类', 'loan',
     '["身份证被冒用", "身份证丢失", "身份被冒用", "冒名贷款", "被注册公司", "征信", "个人信息", "挂失补办"]',
     '身份证丢过一次，后来莫名收到催收电话，一查征信上多出一笔自己从没办过的贷款。',
     '["立刻到户籍地派出所申报丢失并补办，留好报案或补办凭证——这是证明「不是你本人用」的关键", "向征信中心提出异议申请、要求核查并更正；被冒名注册公司的，向市场监管部门申请撤销登记", "向公安机关报案，冒用他人身份证本身就要被处罚，涉犯罪的另追刑责", "涉及贷款、信用卡的，向银行书面声明非本人办理并要求止付；协商不成可起诉确认合同对你无效"]',
     '["cuo-zhuan-zhang", "wangdai-fuwufei", "xinyongka-yuqi"]',
     '2026-10-26', '2026-10-16', '2026-10-16', 'AI 起草 + 人工核对法条', '法条原文已核对官方来源（未做律师复核）', 'published');

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('gongsi-quantui', '《劳动合同法》第 36 条',
     '用人单位与劳动者协商一致，可以解除劳动合同。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 1),
    ('gongsi-quantui', '《劳动合同法》第 46 条',
     '用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的，应当向劳动者支付经济补偿。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('gongsi-quantui', '《劳动合同法》第 47 条',
     '经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 3),
    ('jiaban-fei', '《劳动法》第 44 条',
     '有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬：（一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬；（二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬；（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。',
     'http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296651.html', 1),
    ('jiaban-fei', '《劳动合同法》第 31 条',
     '用人单位应当严格执行劳动定额标准，不得强迫或者变相强迫劳动者加班。用人单位安排加班的，应当按照国家有关规定向劳动者支付加班费。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('shiyongqi-citui', '《劳动合同法》第 19 条',
     '劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。同一用人单位与同一劳动者只能约定一次试用期。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 1),
    ('shiyongqi-citui', '《劳动合同法》第 21 条',
     '在试用期中，除劳动者有本法第三十九条和第四十条第一项、第二项规定的情形外，用人单位不得解除劳动合同。用人单位在试用期解除劳动合同的，应当向劳动者说明理由。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('shiyongqi-citui', '《劳动合同法》第 39 条',
     '劳动者有下列情形之一的，用人单位可以解除劳动合同：（一）在试用期间被证明不符合录用条件的……',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 3),
    ('bu-qian-hetong', '《劳动合同法》第 10 条',
     '建立劳动关系，应当订立书面劳动合同。已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 1),
    ('bu-qian-hetong', '《劳动合同法》第 82 条',
     '用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('caiyuan-peichang', '《劳动合同法》第 40 条',
     '有下列情形之一的，用人单位提前三十日以书面形式通知劳动者本人或者额外支付劳动者一个月工资后，可以解除劳动合同：（一）劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的；（二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的；（三）劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 1),
    ('caiyuan-peichang', '《劳动合同法》第 47 条',
     '经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('caiyuan-peichang', '《劳动合同法》第 87 条',
     '用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 3),
    ('gongshang-rending', '《工伤保险条例》第 14 条',
     '职工有下列情形之一的，应当认定为工伤：（一）在工作时间和工作场所内，因工作原因受到事故伤害的；（二）工作时间前后在工作场所内，从事与工作有关的预备性或者收尾性工作受到事故伤害的；（三）在工作时间和工作场所内，因履行工作职责受到暴力等意外伤害的；（四）患职业病的；（五）因工外出期间，由于工作原因受到伤害或者发生事故下落不明的；（六）在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的；（七）法律、行政法规规定应当认定为工伤的其他情形。',
     'https://www.gov.cn/gongbao/content/2011/content_1778064.htm', 1);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('gongshang-rending', '《工伤保险条例》第 17 条',
     '职工发生事故伤害或者按照职业病防治法规定被诊断、鉴定为职业病，所在单位应当自事故伤害发生之日或者被诊断、鉴定为职业病之日起30日内，向统筹地区社会保险行政部门提出工伤认定申请。遇有特殊情况，经报社会保险行政部门同意，申请时限可以适当延长。用人单位未按前款规定提出工伤认定申请的，工伤职工或者其近亲属、工会组织在事故伤害发生之日或者被诊断、鉴定为职业病之日起1年内，可以直接向用人单位所在地统筹地区社会保险行政部门提出工伤认定申请。',
     'https://www.gov.cn/gongbao/content/2011/content_1778064.htm', 2),
    ('gongshang-rending', '《工伤保险条例》第 33 条',
     '职工因工作遭受事故伤害或者患职业病需要暂停工作接受工伤医疗的，在停工留薪期内，原工资福利待遇不变，由所在单位按月支付。停工留薪期一般不超过12个月。伤情严重或者情况特殊，经设区的市级劳动能力鉴定委员会确认，可以适当延长，但延长不得超过12个月。工伤职工评定伤残等级后，停发原待遇，按照本章的有关规定享受伤残待遇。工伤职工在停工留薪期满后仍需治疗的，继续享受工伤医疗待遇。生活不能自理的工伤职工在停工留薪期需要护理的，由所在单位负责。',
     'https://www.gov.cn/gongbao/content/2011/content_1778064.htm', 3),
    ('shebao-jiaona', '《社会保险法》第 58 条',
     '用人单位应当自用工之日起三十日内为其职工向社会保险经办机构申请办理社会保险登记。未办理社会保险登记的，由社会保险经办机构核定其应当缴纳的社会保险费。',
     'https://www.gov.cn/guoqing/2021-10/29/content_5647616.htm', 1),
    ('shebao-jiaona', '《社会保险法》第 86 条',
     '用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令其限期缴纳或者补足，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，由有关行政部门处欠缴数额一倍以上三倍以下的罚款。',
     'https://www.gov.cn/guoqing/2021-10/29/content_5647616.htm', 2),
    ('shebao-jiaona', '《劳动合同法》第 38 条',
     '用人单位有下列情形之一的，劳动者可以解除劳动合同：（一）未按照劳动合同约定提供劳动保护或者劳动条件的；（二）未及时足额支付劳动报酬的；（三）未依法为劳动者缴纳社会保险费的；（四）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的；（五）因本法第二十六条第一款规定的情形致使劳动合同无效的；（六）法律、行政法规规定用人单位侵犯劳动者合法权益的其他情形。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 3),
    ('nianjia-meixiu', '《职工带薪年休假条例》第 3 条',
     '职工累计工作已满1年不满10年的，年休假5天；已满10年不满20年的，年休假10天；已满20年的，年休假15天。国家法定休假日、休息日不计入年休假的假期。',
     'http://www.npc.gov.cn/npc/c2/c188/c217/201905/t20190522_30040.html', 1),
    ('nianjia-meixiu', '《职工带薪年休假条例》第 5 条',
     '单位根据生产、工作的具体情况，并考虑职工本人意愿，统筹安排职工年休假。年休假在1个年度内可以集中安排，也可以分段安排，一般不跨年度安排。单位因生产、工作特点确有必要跨年度安排职工年休假的，可以跨1个年度安排。单位确因工作需要不能安排职工休年休假的，经职工本人同意，可以不安排职工休年休假。对职工应休未休的年休假天数，单位应当按照该职工日工资收入的300%支付年休假工资报酬。',
     'http://www.npc.gov.cn/npc/c2/c188/c217/201905/t20190522_30040.html', 2),
    ('chanxia-quanyi', '《女职工劳动保护特别规定》第 5 条',
     '用人单位不得因女职工怀孕、生育、哺乳降低其工资、予以辞退、与其解除劳动或者聘用合同。',
     'https://www.gov.cn/zwgk/2012-05/07/content_2131567.htm', 1),
    ('chanxia-quanyi', '《女职工劳动保护特别规定》第 7 条',
     '女职工生育享受98天产假，其中产前可以休假15天；难产的，增加产假15天；生育多胞胎的，每多生育1个婴儿，增加产假15天。女职工怀孕未满4个月流产的，享受15天产假；怀孕满4个月流产的，享受42天产假。',
     'https://www.gov.cn/zwgk/2012-05/07/content_2131567.htm', 2),
    ('chanxia-quanyi', '《劳动合同法》第 42 条',
     '劳动者有下列情形之一的，用人单位不得依照本法第四十条、第四十一条的规定解除劳动合同：（一）从事接触职业病危害作业的劳动者未进行离岗前职业健康检查，或者疑似职业病病人在诊断或者医学观察期间的；（二）在本单位患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的；（三）患病或者非因工负伤，在规定的医疗期内的；（四）女职工在孕期、产期、哺乳期的；（五）在本单位连续工作满十五年，且距法定退休年龄不足五年的；（六）法律、行政法规规定的其他情形。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 3),
    ('jingye-xianzhi', '《劳动合同法》第 23 条',
     '用人单位与劳动者可以在劳动合同中约定保守用人单位的商业秘密和与知识产权相关的保密事项。对负有保密义务的劳动者，用人单位可以在劳动合同或者保密协议中与劳动者约定竞业限制条款，并约定在解除或者终止劳动合同后，在竞业限制期限内按月给予劳动者经济补偿。劳动者违反竞业限制约定的，应当按照约定向用人单位支付违约金。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 1),
    ('jingye-xianzhi', '《劳动合同法》第 24 条',
     '竞业限制的人员限于用人单位的高级管理人员、高级技术人员和其他负有保密义务的人员。竞业限制的范围、地域、期限由用人单位与劳动者约定，竞业限制的约定不得违反法律、法规的规定。在解除或者终止劳动合同后，前款规定的人员到与本单位生产或者经营同类产品、从事同类业务的有竞争关系的其他用人单位，或者自己开业生产或者经营同类产品、从事同类业务的竞业限制期限，不得超过二年。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('mowei-taotai', '《劳动合同法》第 40 条',
     '有下列情形之一的，用人单位提前三十日以书面形式通知劳动者本人或者额外支付劳动者一个月工资后，可以解除劳动合同：（一）劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的；（二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的；（三）劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 1),
    ('mowei-taotai', '《劳动合同法》第 87 条',
     '用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('shixi-jianzhi', '《劳动合同法》第 68 条',
     '非全日制用工，是指以小时计酬为主，劳动者在同一用人单位一般平均每日工作时间不超过四小时，每周工作时间累计不超过二十四小时的用工形式。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 1),
    ('shixi-jianzhi', '《劳动合同法》第 72 条',
     '非全日制用工小时计酬标准不得低于用人单位所在地人民政府规定的最低小时工资标准。非全日制用工劳动报酬结算支付周期最长不得超过十五日。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('cizhi-chengxu', '《劳动合同法》第 37 条',
     '劳动者提前三十日以书面形式通知用人单位，可以解除劳动合同。劳动者在试用期内提前三日通知用人单位，可以解除劳动合同。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 1),
    ('cizhi-chengxu', '《劳动合同法》第 38 条',
     '用人单位有下列情形之一的，劳动者可以解除劳动合同：（一）未按照劳动合同约定提供劳动保护或者劳动条件的；（二）未及时足额支付劳动报酬的；（三）未依法为劳动者缴纳社会保险费的；（四）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的；（五）因本法第二十六条第一款规定的情形致使劳动合同无效的；（六）法律、行政法规规定用人单位侵犯劳动者合法权益的其他情形。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('tuoqian-gongzi', '《劳动合同法》第 30 条',
     '用人单位应当按照劳动合同约定和国家规定，向劳动者及时足额支付劳动报酬。用人单位拖欠或者未足额支付劳动报酬的，劳动者可以依法向当地人民法院申请支付令，人民法院应当依法发出支付令。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 1),
    ('tuoqian-gongzi', '《劳动合同法》第 85 条',
     '用人单位有下列情形之一的，由劳动行政部门责令限期支付劳动报酬、加班费或者经济补偿；劳动报酬低于当地最低工资标准的，应当支付其差额部分；逾期不支付的，责令用人单位按应付金额百分之五十以上百分之一百以下的标准向劳动者加付赔偿金：（一）未按照劳动合同的约定或者国家规定及时足额支付劳动者劳动报酬的；（二）低于当地最低工资标准支付劳动者工资的；（三）安排加班不支付加班费的；（四）解除或者终止劳动合同，未依照本法规定向劳动者支付经济补偿的。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('tuoqian-gongzi', '《劳动法》第 50 条',
     '工资应当以货币形式按月支付给劳动者本人。不得克扣或者无故拖欠劳动者的工资。',
     'http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296651.html', 3),
    ('diaogang-jiangxin', '《劳动合同法》第 35 条',
     '用人单位与劳动者协商一致，可以变更劳动合同约定的内容。变更劳动合同，应当采用书面形式。变更后的劳动合同文本由用人单位和劳动者各执一份。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 1),
    ('diaogang-jiangxin', '《劳动合同法》第 38 条',
     '用人单位有下列情形之一的，劳动者可以解除劳动合同：（一）未按照劳动合同约定提供劳动保护或者劳动条件的；（二）未及时足额支付劳动报酬的；（三）未依法为劳动者缴纳社会保险费的；（四）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的；（五）因本法第二十六条第一款规定的情形致使劳动合同无效的；（六）法律、行政法规规定用人单位侵犯劳动者合法权益的其他情形。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('shiyongqi-gongzi', '《劳动合同法》第 20 条',
     '劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 1),
    ('shiyongqi-gongzi', '《劳动合同法》第 19 条',
     '劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。同一用人单位与同一劳动者只能约定一次试用期。以完成一定工作任务为期限的劳动合同或者劳动合同期限不满三个月的，不得约定试用期。试用期包含在劳动合同期限内。劳动合同仅约定试用期的，试用期不成立，该期限为劳动合同期限。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('jiaban-tiaoxiu', '《劳动法》第 44 条',
     '有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬：（一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬；（二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬；（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。',
     'http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296651.html', 1),
    ('jiaban-tiaoxiu', '《劳动合同法》第 31 条',
     '用人单位应当严格执行劳动定额标准，不得强迫或者变相强迫劳动者加班。用人单位安排加班的，应当按照国家有关规定向劳动者支付加班费。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('laodong-zhongcai', '《劳动争议调解仲裁法》第 27 条',
     '劳动争议申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。前款规定的仲裁时效，因当事人一方向对方当事人主张权利，或者向有关部门请求权利救济，或者对方当事人同意履行义务而中断。从中断时起，仲裁时效期间重新计算。劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出。',
     'http://www.npc.gov.cn/zgrdw/npc/xinwen/lfgz/zxfl/2007-12/29/content_1387809.htm', 1);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('laodong-zhongcai', '《劳动争议调解仲裁法》第 5 条',
     '发生劳动争议，当事人不愿协商、协商不成或者达成和解协议后不履行的，可以向调解组织申请调解；不愿调解、调解不成或者达成调解协议后不履行的，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服的，除本法另有规定的外，可以向人民法院提起诉讼。',
     'http://www.npc.gov.cn/zgrdw/npc/xinwen/lfgz/zxfl/2007-12/29/content_1387809.htm', 2),
    ('gongzuo-shijian', '《劳动法》第 36 条',
     '国家实行劳动者每日工作时间不超过八小时、平均每周工作时间不超过四十四小时的工时制度。',
     'http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296651.html', 1),
    ('gongzuo-shijian', '《劳动法》第 41 条',
     '用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过一小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过三小时，但是每月不得超过三十六小时。',
     'http://www.npc.gov.cn/npc/c2/c30834/201905/t20190521_296651.html', 2),
    ('lisan-zhengming', '《劳动合同法》第 50 条',
     '用人单位应当在解除或者终止劳动合同时出具解除或者终止劳动合同的证明，并在十五日内为劳动者办理档案和社会保险关系转移手续。劳动者应当按照双方约定，办理工作交接。用人单位依照本法有关规定应当向劳动者支付经济补偿的，在办结工作交接时支付。用人单位对已经解除或者终止的劳动合同的文本，至少保存二年备查。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 1),
    ('lisan-zhengming', '《劳动合同法》第 89 条',
     '用人单位违反本法规定未向劳动者出具解除或者终止劳动合同的书面证明，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。',
     'https://www.gov.cn/govweb/gongbao/content/2007/content_711013.htm', 2),
    ('guoqi-shipin', '《食品安全法》第 148 条',
     '生产不符合食品安全标准的食品或者经营明知是不符合食品安全标准的食品，消费者除要求赔偿损失外，还可以向生产者或者经营者要求支付价款十倍或者损失三倍的赔偿金；增加赔偿的金额不足一千元的，为一千元。',
     'https://www.gov.cn/zhengce/2015-04/25/content_2853643.htm', 1),
    ('guoqi-shipin', '《消费者权益保护法》第 24 条',
     '经营者提供的商品或者服务不符合质量要求的，消费者可以依照国家规定、当事人约定退货，或者要求经营者履行更换、修理等义务。没有国家规定和当事人约定的，消费者可以自收到商品之日起七日内退货；七日后符合法定解除合同条件的，消费者可以及时退货，不符合法定解除合同条件的，可以要求经营者履行更换、修理等义务。依照前款规定进行退货、更换、修理的，经营者应当承担运输等必要费用。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2),
    ('qitian-wuliyou', '《消费者权益保护法》第 25 条',
     '经营者采用网络、电视、电话、邮购等方式销售商品，消费者有权自收到商品之日起七日内退货，且无需说明理由，但下列商品除外：（一）消费者定作的；（二）鲜活易腐的；（三）在线下载或者消费者拆封的音像制品、计算机软件等数字化商品；（四）交付的报纸、期刊。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 1),
    ('qitian-wuliyou', '《消费者权益保护法》第 23 条',
     '经营者应当保证在正常使用商品或者接受服务的情况下其提供的商品或者服务应当具有的质量、性能、用途和有效期限；但消费者在购买该商品或者接受该服务前已经知道其存在瑕疵，且存在该瑕疵不违反法律强制性规定的除外。经营者以广告、产品说明、实物样品或者其他方式表明商品或者服务的质量状况的，应当保证其提供的商品或者服务的实际质量与表明的质量状况相符。经营者提供的机动车、计算机、电视机、电冰箱、空调器、洗衣机等耐用商品或者装饰装修等服务，消费者自接受商品或者服务之日起六个月内发现瑕疵，发生争议的，由经营者承担有关瑕疵的举证责任。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2),
    ('yufuka-paolu', '《消费者权益保护法》第 53 条',
     '经营者以预收款方式提供商品或者服务的，应当按照约定提供。未按照约定提供的，应当按照消费者的要求履行约定或者退回预付款；并应当承担预付款的利息、消费者必须支付的合理费用。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 1),
    ('yufuka-paolu', '《民法典》第 577 条',
     '当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('xujia-xuanchuan', '《消费者权益保护法》第 55 条',
     '经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 1),
    ('xujia-xuanchuan', '《消费者权益保护法》第 20 条',
     '经营者向消费者提供有关商品或者服务的质量、性能、用途、有效期限等信息，应当真实、全面，不得作虚假或者引人误解的宣传。经营者对消费者就其提供的商品或者服务的质量和使用方法等问题提出的询问，应当作出真实、明确的答复。经营者提供商品或者服务应当明码标价。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2),
    ('tuikuan-nan', '《消费者权益保护法》第 24 条',
     '经营者提供的商品或者服务不符合质量要求的，消费者可以依照国家规定、当事人约定退货，或者要求经营者履行更换、修理等义务。没有国家规定和当事人约定的，消费者可以自收到商品之日起七日内退货；七日后符合法定解除合同条件的，消费者可以及时退货，不符合法定解除合同条件的，可以要求经营者履行更换、修理等义务。依照前款规定进行退货、更换、修理的，经营者应当承担运输等必要费用。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 1);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('tuikuan-nan', '《消费者权益保护法》第 25 条',
     '经营者采用网络、电视、电话、邮购等方式销售商品，消费者有权自收到商品之日起七日内退货，且无需说明理由，但下列商品除外：（一）消费者定作的；（二）鲜活易腐的；（三）在线下载或者消费者拆封的音像制品、计算机软件等数字化商品；（四）交付的报纸、期刊。除前款所列商品外，其他根据商品性质并经消费者在购买时确认不宜退货的商品，不适用无理由退货。消费者退货的商品应当完好。经营者应当自收到退回商品之日起七日内返还消费者支付的商品价款。退回商品的运费由消费者承担；经营者和消费者另有约定的，按照约定。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2),
    ('maijia-jiahuo', '《消费者权益保护法》第 55 条',
     '经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。经营者明知商品或者服务存在缺陷，仍然向消费者提供，造成消费者或者其他受害人死亡或者健康严重损害的，受害人有权要求经营者依照本法第四十九条、第五十一条等法律规定赔偿损失，并有权要求所受损失二倍以下的惩罚性赔偿。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 1),
    ('maijia-jiahuo', '《消费者权益保护法》第 24 条',
     '经营者提供的商品或者服务不符合质量要求的，消费者可以依照国家规定、当事人约定退货，或者要求经营者履行更换、修理等义务。没有国家规定和当事人约定的，消费者可以自收到商品之日起七日内退货；七日后符合法定解除合同条件的，消费者可以及时退货，不符合法定解除合同条件的，可以要求经营者履行更换、修理等义务。依照前款规定进行退货、更换、修理的，经营者应当承担运输等必要费用。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2),
    ('dingjin-yudingjin', '《民法典》第 586 条',
     '当事人可以约定一方向对方给付定金作为债权的担保。定金合同自实际交付定金时成立。定金的数额由当事人约定；但是，不得超过主合同标的额的百分之二十，超过部分不产生定金的效力。实际交付的定金数额多于或者少于约定数额的，视为变更约定的定金数额。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('dingjin-yudingjin', '《民法典》第 587 条',
     '债务人履行债务的，定金应当抵作价款或者收回。给付定金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，无权请求返还定金；收受定金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，应当双倍返还定金。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('sanbao-weixiu', '《消费者权益保护法》第 24 条',
     '经营者提供的商品或者服务不符合质量要求的，消费者可以依照国家规定、当事人约定退货，或者要求经营者履行更换、修理等义务。没有国家规定和当事人约定的，消费者可以自收到商品之日起七日内退货；七日后符合法定解除合同条件的，消费者可以及时退货，不符合法定解除合同条件的，可以要求经营者履行更换、修理等义务。依照前款规定进行退货、更换、修理的，经营者应当承担运输等必要费用。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 1),
    ('sanbao-weixiu', '《消费者权益保护法》第 23 条',
     '经营者应当保证在正常使用商品或者接受服务的情况下其提供的商品或者服务应当具有的质量、性能、用途和有效期限；但消费者在购买该商品或者接受该服务前已经知道其存在瑕疵，且存在该瑕疵不违反法律强制性规定的除外。经营者以广告、产品说明、实物样品或者其他方式表明商品或者服务的质量状况的，应当保证其提供的商品或者服务的实际质量与表明的质量状况相符。经营者提供的机动车、计算机、电视机、电冰箱、空调器、洗衣机等耐用商品或者装饰装修等服务，消费者自接受商品或者服务之日起六个月内发现瑕疵，发生争议的，由经营者承担有关瑕疵的举证责任。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2),
    ('zengpin-zeren', '《民法典》第 662 条',
     '赠与的财产有瑕疵的，赠与人不承担责任。附义务的赠与，赠与的财产有瑕疵的，赠与人在附义务的限度内承担与出卖人相同的责任。赠与人故意不告知瑕疵或者保证无瑕疵，造成受赠人损失的，应当承担赔偿责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('zengpin-zeren', '《消费者权益保护法》第 20 条',
     '经营者向消费者提供有关商品或者服务的质量、性能、用途、有效期限等信息，应当真实、全面，不得作虚假或者引人误解的宣传。经营者对消费者就其提供的商品或者服务的质量和使用方法等问题提出的询问，应当作出真实、明确的答复。经营者提供商品或者服务应当明码标价。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2),
    ('chichu-yiwu', '《食品安全法》第 148 条',
     '消费者因不符合食品安全标准的食品受到损害的，可以向经营者要求赔偿损失，也可以向生产者要求赔偿损失。接到消费者赔偿要求的生产经营者，应当实行首负责任制，先行赔付，不得推诿；属于生产者责任的，经营者赔偿后有权向生产者追偿；属于经营者责任的，生产者赔偿后有权向经营者追偿。生产不符合食品安全标准的食品或者经营明知是不符合食品安全标准的食品，消费者除要求赔偿损失外，还可以向生产者或者经营者要求支付价款十倍或者损失三倍的赔偿金；增加赔偿的金额不足一千元的，为一千元。但是，食品的标签、说明书存在不影响食品安全且不会对消费者造成误导的瑕疵的除外。',
     'https://www.gov.cn/zhengce/2015-04/25/content_2853643.htm', 1),
    ('chichu-yiwu', '《食品安全法》第 34 条',
     '禁止生产经营下列食品、食品添加剂、食品相关产品：（一）用非食品原料生产的食品或者添加食品添加剂以外的化学物质和其他可能危害人体健康物质的食品，或者用回收食品作为原料生产的食品；（二）致病性微生物，农药残留、兽药残留、生物毒素、重金属等污染物质以及其他危害人体健康的物质含量超过食品安全标准限量的食品、食品添加剂、食品相关产品；（三）用超过保质期的食品原料、食品添加剂生产的食品、食品添加剂；（四）超范围、超限量使用食品添加剂的食品；（五）营养成分不符合食品安全标准的专供婴幼儿和其他特定人群的主辅食品；（六）腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物、掺假掺杂或者感官性状异常的食品、食品添加剂；（七）病死、毒死或者死因不明的禽、畜、兽、水产动物肉类及其制品；（八）未按规定进行检疫或者检疫不合格的肉类，或者未经检验或者检验不合格的肉类制品；（九）被包装材料、容器、运输工具等污染的食品、食品添加剂；（十）标注虚假生产日期、保质期或者超过保质期的食品、食品添加剂；（十一）无标签的预包装食品、食品添加剂；（十二）国家为防病等特殊需要明令禁止生产经营的食品；（十三）其他不符合法律、法规或者食品安全标准的食品、食品添加剂、食品相关产品。',
     'https://www.gov.cn/zhengce/2015-04/25/content_2853643.htm', 2),
    ('zhibo-daigou', '《消费者权益保护法》第 44 条',
     '消费者通过网络交易平台购买商品或者接受服务，其合法权益受到损害的，可以向销售者或者服务者要求赔偿。网络交易平台提供者不能提供销售者或者服务者的真实名称、地址和有效联系方式的，消费者也可以向网络交易平台提供者要求赔偿；网络交易平台提供者作出更有利于消费者的承诺的，应当履行承诺。网络交易平台提供者赔偿后，有权向销售者或者服务者追偿。网络交易平台提供者明知或者应知销售者或者服务者利用其平台侵害消费者合法权益，未采取必要措施的，依法与该销售者或者服务者承担连带责任。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 1),
    ('zhibo-daigou', '《消费者权益保护法》第 55 条',
     '经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2),
    ('bawang-tiaokuan', '《民法典》第 496 条',
     '格式条款是当事人为了重复使用而预先拟定，并在订立合同时未与对方协商的条款。采用格式条款订立合同的，提供格式条款的一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理的方式提示对方注意免除或者减轻其责任等与对方有重大利害关系的条款，按照对方的要求，对该条款予以说明。提供格式条款的一方未履行提示或者说明义务，致使对方没有注意或者理解与其有重大利害关系的条款的，对方可以主张该条款不成为合同的内容。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('bawang-tiaokuan', '《民法典》第 497 条',
     '有下列情形之一的，该格式条款无效：（一）具有本法第一编第六章第三节和本法第五百零六条规定的无效情形；（二）提供格式条款一方不合理地免除或者减轻其责任、加重对方责任、限制对方主要权利；（三）提供格式条款一方排除对方主要权利。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('jiage-qizha', '《消费者权益保护法》第 20 条',
     '经营者向消费者提供有关商品或者服务的质量、性能、用途、有效期限等信息，应当真实、全面，不得作虚假或者引人误解的宣传。经营者对消费者就其提供的商品或者服务的质量和使用方法等问题提出的询问，应当作出真实、明确的答复。经营者提供商品或者服务应当明码标价。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 1),
    ('jiage-qizha', '《消费者权益保护法》第 55 条',
     '经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2),
    ('juzheng-zeren', '《消费者权益保护法》第 23 条',
     '经营者应当保证在正常使用商品或者接受服务的情况下其提供的商品或者服务应当具有的质量、性能、用途和有效期限；但消费者在购买该商品或者接受该服务前已经知道其存在瑕疵，且存在该瑕疵不违反法律强制性规定的除外。经营者以广告、产品说明、实物样品或者其他方式表明商品或者服务的质量状况的，应当保证其提供的商品或者服务的实际质量与表明的质量状况相符。经营者提供的机动车、计算机、电视机、电冰箱、空调器、洗衣机等耐用商品或者装饰装修等服务，消费者自接受商品或者服务之日起六个月内发现瑕疵，发生争议的，由经营者承担有关瑕疵的举证责任。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 1),
    ('juzheng-zeren', '《消费者权益保护法》第 24 条',
     '经营者提供的商品或者服务不符合质量要求的，消费者可以依照国家规定、当事人约定退货，或者要求经营者履行更换、修理等义务。没有国家规定和当事人约定的，消费者可以自收到商品之日起七日内退货；七日后符合法定解除合同条件的，消费者可以及时退货，不符合法定解除合同条件的，可以要求经营者履行更换、修理等义务。依照前款规定进行退货、更换、修理的，经营者应当承担运输等必要费用。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2),
    ('peixun-tuifei', '《消费者权益保护法》第 53 条',
     '经营者以预收款方式提供商品或者服务的，应当按照约定提供。未按照约定提供的，应当按照消费者的要求履行约定或者退回预付款；并应当承担预付款的利息、消费者必须支付的合理费用。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 1),
    ('peixun-tuifei', '《民法典》第 577 条',
     '当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('chanpin-zeren', '《民法典》第 1202 条',
     '因产品存在缺陷造成他人损害的，生产者应当承担侵权责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('chanpin-zeren', '《民法典》第 1203 条',
     '因产品存在缺陷造成他人损害的，被侵权人可以向产品的生产者请求赔偿，也可以向产品的销售者请求赔偿。产品缺陷由生产者造成的，销售者赔偿后，有权向生产者追偿。因销售者的过错使产品存在缺陷的，生产者赔偿后，有权向销售者追偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('chanpin-zeren', '《民法典》第 1207 条',
     '明知产品存在缺陷仍然生产、销售，或者没有依据前条规定采取有效补救措施，造成他人死亡或者健康严重损害的，被侵权人有权请求相应的惩罚性赔偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 3),
    ('renshang-peichang', '《消费者权益保护法》第 49 条',
     '经营者提供商品或者服务，造成消费者或者其他受害人人身伤害的，应当赔偿医疗费、护理费、交通费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿残疾生活辅助具费和残疾赔偿金。造成死亡的，还应当赔偿丧葬费和死亡赔偿金。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 1),
    ('renshang-peichang', '《民法典》第 1179 条',
     '侵害他人造成人身损害的，应当赔偿医疗费、护理费、交通费、营养费、住院伙食补助费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿辅助器具费和残疾赔偿金；造成死亡的，还应当赔偿丧葬费和死亡赔偿金。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('kanjia-weiyue', '《民法典》第 577 条',
     '当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('kanjia-weiyue', '《消费者权益保护法》第 20 条',
     '经营者向消费者提供有关商品或者服务的质量、性能、用途、有效期限等信息，应当真实、全面，不得作虚假或者引人误解的宣传。经营者对消费者就其提供的商品或者服务的质量和使用方法等问题提出的询问，应当作出真实、明确的答复。经营者提供商品或者服务应当明码标价。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('pingtai-zeren', '《消费者权益保护法》第 44 条',
     '消费者通过网络交易平台购买商品或者接受服务，其合法权益受到损害的，可以向销售者或者服务者要求赔偿。网络交易平台提供者不能提供销售者或者服务者的真实名称、地址和有效联系方式的，消费者也可以向网络交易平台提供者要求赔偿；网络交易平台提供者作出更有利于消费者的承诺的，应当履行承诺。网络交易平台提供者赔偿后，有权向销售者或者服务者追偿。网络交易平台提供者明知或者应知销售者或者服务者利用其平台侵害消费者合法权益，未采取必要措施的，依法与该销售者或者服务者承担连带责任。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 1),
    ('pingtai-zeren', '《消费者权益保护法》第 24 条',
     '经营者提供的商品或者服务不符合质量要求的，消费者可以依照国家规定、当事人约定退货，或者要求经营者履行更换、修理等义务。没有国家规定和当事人约定的，消费者可以自收到商品之日起七日内退货；七日后符合法定解除合同条件的，消费者可以及时退货，不符合法定解除合同条件的，可以要求经营者履行更换、修理等义务。依照前款规定进行退货、更换、修理的，经营者应当承担运输等必要费用。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2),
    ('xufei-koufei', '《民法典》第 496 条',
     '格式条款是当事人为了重复使用而预先拟定，并在订立合同时未与对方协商的条款。采用格式条款订立合同的，提供格式条款的一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理的方式提示对方注意免除或者减轻其责任等与对方有重大利害关系的条款，按照对方的要求，对该条款予以说明。提供格式条款的一方未履行提示或者说明义务，致使对方没有注意或者理解与其有重大利害关系的条款的，对方可以主张该条款不成为合同的内容。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('xufei-koufei', '《消费者权益保护法》第 20 条',
     '经营者向消费者提供有关商品或者服务的质量、性能、用途、有效期限等信息，应当真实、全面，不得作虚假或者引人误解的宣传。经营者对消费者就其提供的商品或者服务的质量和使用方法等问题提出的询问，应当作出真实、明确的答复。经营者提供商品或者服务应当明码标价。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 2),
    ('pengyou-jietiao', '《民法典》第 667 条',
     '借款合同是借款人向贷款人借款，到期返还借款并支付利息的合同。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('pengyou-jietiao', '《民法典》第 188 条',
     '向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('zhiyou-zhuanzhang', '《民法典》第 679 条',
     '自然人之间的借款合同，自贷款人提供借款时成立。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('zhiyou-zhuanzhang', '《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第 16 条',
     '原告仅依据金融机构的转账凭证提起民间借贷诉讼，被告抗辩转账系偿还双方之前借款或者其他债务的，被告应当对其主张提供证据证明。被告提供相应证据证明其主张后，原告仍应就借贷关系的成立承担举证责任。',
     'https://cicc.court.gov.cn/html/1/218/62/84/12844.html', 2),
    ('lixi-shangxian', '《民法典》第 680 条',
     '禁止高利放贷，借款的利率不得违反国家有关规定。借款合同对支付利息没有约定的，视为没有利息。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('lixi-shangxian', '《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第 25 条',
     '出借人请求借款人按照合同约定利率支付利息的，人民法院应予支持，但是双方约定的利率超过合同成立时一年期贷款市场报价利率四倍的除外。',
     'https://cicc.court.gov.cn/html/1/218/62/84/12844.html', 2),
    ('danbaoren', '《民法典》第 686 条',
     '保证的方式包括一般保证和连带责任保证。当事人在保证合同中对保证方式没有约定或者约定不明确的，按照一般保证承担保证责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('danbaoren', '《民法典》第 692 条',
     '债权人与保证人可以约定保证期间，但是约定的保证期间早于主债务履行期限或者与主债务履行期限同时届满的，视为没有约定；没有约定或者约定不明确的，保证期间为主债务履行期限届满之日起六个月。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('kan-tou-xi', '《民法典》第 670 条',
     '借款的利息不得预先在本金中扣除。利息预先在本金中扣除的，应当按照实际借款数额返还借款并计算利息。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('kan-tou-xi', '《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第 25 条',
     '出借人请求借款人按照合同约定利率支付利息的，人民法院应予支持，但是双方约定的利率超过合同成立时一年期贷款市场报价利率四倍的除外。前款所称“一年期贷款市场报价利率”，是指中国人民银行授权全国银行间同业拆借中心自2019年8月20日起每月发布的一年期贷款市场报价利率。',
     'https://cicc.court.gov.cn/html/1/218/62/84/12844.html', 2);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('cuishou-raoluan', '《治安管理处罚法》第 50 条',
     '有下列行为之一的，处五日以下拘留或者一千元以下罚款；情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款：（一）写恐吓信或者以其他方法威胁他人人身安全的；（二）公然侮辱他人或者捏造事实诽谤他人的；（三）捏造事实诬告陷害他人，企图使他人受到刑事追究或者受到治安管理处罚的；（四）对证人及其近亲属进行威胁、侮辱、殴打或者打击报复的；（五）多次发送淫秽、侮辱、恐吓等信息或者采取滋扰、纠缠、跟踪等方法，干扰他人正常生活的；（六）偷窥、偷拍、窃听、散布他人隐私的。有前款第五项规定的滋扰、纠缠、跟踪行为的，除依照前款规定给予处罚外，经公安机关负责人批准，可以责令其一定期限内禁止接触被侵害人。对违反禁止接触规定的，处五日以上十日以下拘留，可以并处一千元以下罚款。',
     'http://www.npc.gov.cn/c2/c30834/202506/t20250627_446254.html', 1),
    ('cuishou-raoluan', '《民法典》第 1032 条',
     '自然人享有隐私权。任何组织或者个人不得以刺探、侵扰、泄露、公开等方式侵害他人的隐私权。隐私是自然人的私人生活安宁和不愿为他人知晓的私密空间、私密活动、私密信息。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('cuishou-raoluan', '《民法典》第 1033 条',
     '除法律另有规定或者权利人明确同意外，任何组织或者个人不得实施下列行为：（一）以电话、短信、即时通讯工具、电子邮件、传单等方式侵扰他人的私人生活安宁；（二）进入、拍摄、窥视他人的住宅、宾馆房间等私密空间；（三）拍摄、窥视、窃听、公开他人的私密活动；（四）拍摄、窥视他人身体的私密部位；（五）处理他人的私密信息；（六）以其他方式侵害他人的隐私权。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 3),
    ('huankuan-shunxu', '《民法典》第 561 条',
     '债务人在履行主债务外还应当支付利息和实现债权的有关费用，其给付不足以清偿全部债务的，除当事人另有约定外，应当按照下列顺序履行：（一）实现债权的有关费用；（二）利息；（三）主债务。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('huankuan-shunxu', '《民法典》第 676 条',
     '借款人未按照约定的期限返还借款的，应当按照约定或者国家有关规定支付逾期利息。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('li-gun-li', '《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第 28 条',
     '借贷双方对前期借款本息结算后将利息计入后期借款本金并重新出具债权凭证，如果前期利率没有超过合同成立时一年期贷款市场报价利率四倍，重新出具的债权凭证载明的金额可认定为后期借款本金。超过部分的利息，不应认定为后期借款本金。借前款计算，借款人在借款期间届满后应当支付的本息之和，超过以最初借款本金与以最初借款本金为基数、以合同成立时一年期贷款市场报价利率四倍计算的整个借款期间的利息之和的，人民法院不予支持。',
     'https://cicc.court.gov.cn/html/1/218/62/84/12844.html', 1),
    ('li-gun-li', '《民法典》第 680 条',
     '禁止高利放贷，借款的利率不得违反国家有关规定。借款合同对支付利息没有约定的，视为没有利息。借款合同对支付利息约定不明确，当事人不能达成补充协议的，按照当地或者当事人的交易方式、交易习惯、市场利率等因素确定利息；自然人之间借款的，视为没有利息。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('yuqi-lixi-fajin', '《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第 28 条',
     '借贷双方对逾期利率有约定的，从其约定，但是以不超过合同成立时一年期贷款市场报价利率四倍为限。未约定逾期利率或者约定不明的，人民法院可以区分不同情况处理：（一）既未约定借期内利率，也未约定逾期利率，出借人主张借款人自逾期还款之日起参照当时一年期贷款市场报价利率标准计算的利息承担逾期还款违约责任的，人民法院应予支持；（二）约定了借期内利率但是未约定逾期利率，出借人主张借款人自逾期还款之日起按照借期内利率支付资金占用期间利息的，人民法院应予支持。',
     'https://cicc.court.gov.cn/html/1/218/62/84/12844.html', 1),
    ('yuqi-lixi-fajin', '《民法典》第 676 条',
     '借款人未按照约定的期限返还借款的，应当按照约定或者国家有关规定支付逾期利息。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('fufu-gongzhai', '《民法典》第 1064 条',
     '夫妻双方共同签名或者夫妻一方事后追认等共同意思表示所负的债务，以及夫妻一方在婚姻关系存续期间以个人名义为家庭日常生活需要所负的债务，属于夫妻共同债务。夫妻一方在婚姻关系存续期间以个人名义超出家庭日常生活需要所负的债务，不属于夫妻共同债务；但是，债权人能够证明该债务用于夫妻共同生活、共同生产经营或者基于夫妻双方共同意思表示的除外。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('fufu-gongzhai', '《民法典》第 1089 条',
     '离婚时，夫妻共同债务应当共同偿还。共同财产不足清偿或者财产归各自所有的，由双方协议清偿；协议不成的，由人民法院判决。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('yichan-zhaiwu', '《民法典》第 1161 条',
     '继承人以所得遗产实际价值为限清偿被继承人依法应当缴纳的税款和债务。超过遗产实际价值部分，继承人自愿偿还的不在此限。继承人放弃继承的，对被继承人依法应当缴纳的税款和债务可以不负清偿责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('yichan-zhaiwu', '《民法典》第 1127 条',
     '遗产按照下列顺序继承：（一）第一顺序：配偶、子女、父母；（二）第二顺序：兄弟姐妹、祖父母、外祖父母。继承开始后，由第一顺序继承人继承，第二顺序继承人不继承；没有第一顺序继承人继承的，由第二顺序继承人继承。本编所称子女，包括婚生子女、非婚生子女、养子女和有扶养关系的继子女。本编所称父母，包括生父母、养父母和有扶养关系的继父母。本编所称兄弟姐妹，包括同父母的兄弟姐妹、同父异母或者同母异父的兄弟姐妹、养兄弟姐妹、有扶养关系的继兄弟姐妹。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('duzhai-wuxiao', '《民法典》第 153 条',
     '违反法律、行政法规的强制性规定的民事法律行为无效。但是，该强制性规定不导致该民事法律行为无效的除外。违背公序良俗的民事法律行为无效。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('duzhai-wuxiao', '《治安管理处罚法》第 50 条',
     '有下列行为之一的，处五日以下拘留或者一千元以下罚款；情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款：（一）写恐吓信或者以其他方法威胁他人人身安全的；（二）公然侮辱他人或者捏造事实诽谤他人的；（三）捏造事实诬告陷害他人，企图使他人受到刑事追究或者受到治安管理处罚的；（四）对证人及其近亲属进行威胁、侮辱、殴打或者打击报复的；（五）多次发送淫秽、侮辱、恐吓等信息或者采取滋扰、纠缠、跟踪等方法，干扰他人正常生活的；（六）偷窥、偷拍、窃听、散布他人隐私的。有前款第五项规定的滋扰、纠缠、跟踪行为的，除依照前款规定给予处罚外，经公安机关负责人批准，可以责令其一定期限内禁止接触被侵害人。对违反禁止接触规定的，处五日以上十日以下拘留，可以并处一千元以下罚款。',
     'http://www.npc.gov.cn/c2/c30834/202506/t20250627_446254.html', 2),
    ('wangdai-fuwufei', '《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第 25 条',
     '出借人请求借款人按照合同约定利率支付利息的，人民法院应予支持，但是双方约定的利率超过合同成立时一年期贷款市场报价利率四倍的除外。前款所称“一年期贷款市场报价利率”，是指中国人民银行授权全国银行间同业拆借中心自2019年8月20日起每月发布的一年期贷款市场报价利率。',
     'https://cicc.court.gov.cn/html/1/218/62/84/12844.html', 1),
    ('wangdai-fuwufei', '《民法典》第 680 条',
     '禁止高利放贷，借款的利率不得违反国家有关规定。借款合同对支付利息没有约定的，视为没有利息。借款合同对支付利息约定不明确，当事人不能达成补充协议的，按照当地或者当事人的交易方式、交易习惯、市场利率等因素确定利息；自然人之间借款的，视为没有利息。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('xinyongka-yuqi', '《民法典》第 675 条',
     '借款人应当按照约定的期限返还借款。对借款期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，借款人可以随时返还；贷款人可以催告借款人在合理期限内返还。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('xinyongka-yuqi', '《民法典》第 676 条',
     '借款人未按照约定的期限返还借款的，应当按照约定或者国家有关规定支付逾期利息。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('susong-shixiao', '《民法典》第 188 条',
     '向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。诉讼时效期间自权利人知道或者应当知道权利受到损害以及义务人之日起计算。法律另有规定的，依照其规定。但是，自权利受到损害之日起超过二十年的，人民法院不予保护，有特殊情况的，人民法院可以根据权利人的申请决定延长。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('susong-shixiao', '《民法典》第 675 条',
     '借款人应当按照约定的期限返还借款。对借款期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，借款人可以随时返还；贷款人可以催告借款人在合理期限内返还。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('qinqi-jieqian-lixi', '《民法典》第 679 条',
     '自然人之间的借款合同，自贷款人提供借款时成立。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('qinqi-jieqian-lixi', '《民法典》第 680 条',
     '禁止高利放贷，借款的利率不得违反国家有关规定。借款合同对支付利息没有约定的，视为没有利息。借款合同对支付利息约定不明确，当事人不能达成补充协议的，按照当地或者当事人的交易方式、交易习惯、市场利率等因素确定利息；自然人之间借款的，视为没有利息。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('liaotian-jielu', '《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第 2 条',
     '出借人向人民法院提起民间借贷诉讼时，应当提供借据、收据、欠条等债权凭证以及其他能够证明借贷法律关系存在的证据。当事人持有的借据、收据、欠条等债权凭证没有载明债权人，持有债权凭证的当事人提起民间借贷诉讼的，人民法院应予受理。被告对原告的债权人资格提出有事实依据的抗辩，人民法院经审查认为原告不具有债权人资格的，裁定驳回起诉。',
     'https://cicc.court.gov.cn/html/1/218/62/84/12844.html', 1),
    ('liaotian-jielu', '《民法典》第 668 条',
     '借款合同应当采用书面形式，但是自然人之间借款另有约定的除外。借款合同的内容一般包括借款种类、币种、用途、数额、利率、期限和还款方式等条款。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('cuo-zhuan-zhang', '《民法典》第 985 条',
     '得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但是有下列情形之一的除外：（一）为履行道德义务进行的给付；（二）债务到期之前的清偿；（三）明知无给付义务而进行的债务清偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('cuo-zhuan-zhang', '《民法典》第 987 条',
     '得利人知道或者应当知道取得的利益没有法律根据的，受损失的人可以请求得利人返还其取得的利益并依法赔偿损失。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('xieyi-huankuan', '《民法典》第 509 条',
     '当事人应当按照约定全面履行自己的义务。当事人应当遵循诚信原则，根据合同的性质、目的和交易习惯履行通知、协助、保密等义务。当事人在履行合同过程中，应当避免浪费资源、污染环境和破坏生态。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('xieyi-huankuan', '《民法典》第 675 条',
     '借款人应当按照约定的期限返还借款。对借款期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，借款人可以随时返还；贷款人可以催告借款人在合理期限内返还。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('liuyu-tiaokuan', '《民法典》第 401 条',
     '抵押权人在债务履行期限届满前，与抵押人约定债务人不履行到期债务时抵押财产归债权人所有的，只能依法就抵押财产优先受偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('liuyu-tiaokuan', '《民法典》第 394 条',
     '为担保债务的履行，债务人或者第三人不转移财产的占有，将该财产抵押给债权人的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，债权人有权就该财产优先受偿。前款规定的债务人或者第三人为抵押人，债权人为抵押权人，提供担保的财产为抵押财产。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('fangdong-bu-tui-yajin', '《民法典》第 714 条',
     '承租人应当妥善保管租赁物，因保管不善造成租赁物毁损、灭失的，应当承担赔偿责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('fangdong-bu-tui-yajin', '《民法典》第 733 条',
     '租赁期限届满，承租人应当返还租赁物。返还的租赁物应当符合按照约定或者根据租赁物的性质使用后的状态。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('lihun-fangchan', '《民法典》第 1062 条',
     '夫妻在婚姻关系存续期间所得的下列财产，为夫妻的共同财产，归夫妻共同所有：（一）工资、奖金、劳务报酬；（二）生产、经营、投资的收益；（三）知识产权的收益；（四）继承或者受赠的财产，但是本法第一千零六十三条第三项规定的除外；（五）其他应当归共同所有的财产。夫妻对共同财产，有平等的处理权。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('lihun-fangchan', '《民法典》第 1087 条',
     '离婚时，夫妻的共同财产由双方协议处理；协议不成的，由人民法院根据财产的具体情况，按照照顾子女、女方和无过错方权益的原则判决。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('caili-fanhuan', '《民法典》第 1042 条',
     '禁止包办、买卖婚姻和其他干涉婚姻自由的行为。禁止借婚姻索取财物。禁止重婚。禁止有配偶者与他人同居。禁止家庭暴力。禁止家庭成员间的虐待和遗弃。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('caili-fanhuan', '《最高人民法院关于审理涉彩礼纠纷案件适用法律若干问题的规定》第 5 条',
     '双方已办理结婚登记且共同生活，离婚时一方请求返还按照习俗给付的彩礼的，人民法院一般不予支持。但是，如果共同生活时间较短且彩礼数额过高的，人民法院可以根据彩礼实际使用及嫁妆情况，综合考虑彩礼数额、共同生活及孕育情况、双方过错等事实，结合当地习俗，确定是否返还以及返还的具体比例。',
     'https://www.court.gov.cn/fabu/xiangqing/423442.html', 2),
    ('caili-fanhuan', '《最高人民法院关于审理涉彩礼纠纷案件适用法律若干问题的规定》第 6 条',
     '双方未办理结婚登记但已共同生活，一方请求返还按照习俗给付的彩礼的，人民法院应当根据彩礼实际使用及嫁妆情况，综合考虑共同生活及孕育情况、双方过错等事实，结合当地习俗，确定是否返还以及返还的具体比例。',
     'https://www.court.gov.cn/fabu/xiangqing/423442.html', 3),
    ('yichan-fenpei', '《民法典》第 1123 条',
     '继承开始后，按照法定继承办理；有遗嘱的，按照遗嘱继承或者遗赠办理；有遗赠扶养协议的，按照协议办理。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('yichan-fenpei', '《民法典》第 1127 条',
     '遗产按照下列顺序继承：（一）第一顺序：配偶、子女、父母；（二）第二顺序：兄弟姐妹、祖父母、外祖父母。继承开始后，由第一顺序继承人继承，第二顺序继承人不继承；没有第一顺序继承人继承的，由第二顺序继承人继承。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('jiabao-shenqing', '《反家庭暴力法》第 2 条',
     '本法所称家庭暴力，是指家庭成员之间以殴打、捆绑、残害、限制人身自由以及经常性谩骂、恐吓等方式实施的身体、精神等侵害行为。',
     'https://www.gov.cn/zhengce/2015-12/28/content_5029898.htm', 1),
    ('jiabao-shenqing', '《反家庭暴力法》第 23 条',
     '当事人因遭受家庭暴力或者面临家庭暴力的现实危险，向人民法院申请人身安全保护令的，人民法院应当受理。当事人是无民事行为能力人、限制民事行为能力人，或者因受到强制、威吓等原因无法申请人身安全保护令的，其近亲属、公安机关、妇女联合会、居民委员会、村民委员会、救助管理机构可以代为申请。',
     'https://www.gov.cn/zhengce/2015-12/28/content_5029898.htm', 2);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('jiabao-shenqing', '《反家庭暴力法》第 29 条',
     '人身安全保护令可以包括下列措施：（一）禁止被申请人实施家庭暴力；（二）禁止被申请人骚扰、跟踪、接触申请人及其相关近亲属；（三）责令被申请人迁出申请人住所；（四）保护申请人人身安全的其他措施。',
     'https://www.gov.cn/zhengce/2015-12/28/content_5029898.htm', 3),
    ('jiabao-lihun', '《民法典》第 1079 条',
     '夫妻一方要求离婚的，可以由有关组织进行调解或者直接向人民法院提起离婚诉讼。人民法院审理离婚案件，应当进行调解；如果感情确已破裂，调解无效的，应当准予离婚。有下列情形之一，调解无效的，应当准予离婚：（一）重婚或者与他人同居；（二）实施家庭暴力或者虐待、遗弃家庭成员；（三）有赌博、吸毒等恶习屡教不改；（四）因感情不和分居满二年；（五）其他导致夫妻感情破裂的情形。一方被宣告失踪，另一方提起离婚诉讼的，应当准予离婚。经人民法院判决不准离婚后，双方又分居满一年，一方再次提起离婚诉讼的，应当准予离婚。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('jiabao-lihun', '《民法典》第 1091 条',
     '有下列情形之一，导致离婚的，无过错方有权请求损害赔偿：（一）重婚；（二）与他人同居；（三）实施家庭暴力；（四）虐待、遗弃家庭成员；（五）有其他重大过错。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('jiabao-lihun', '《反家庭暴力法》第 20 条',
     '人民法院审理涉及家庭暴力的案件，可以根据公安机关出警记录、告诫书、伤情鉴定意见等证据，认定家庭暴力事实。',
     'https://www.gov.cn/zhengce/2015-12/28/content_5029898.htm', 3),
    ('lihun-lengjingqi', '《民法典》第 1077 条',
     '自婚姻登记机关收到离婚登记申请之日起三十日内，任何一方不愿意离婚的，可以向婚姻登记机关撤回离婚登记申请。前款规定期限届满后三十日内，双方应当亲自到婚姻登记机关申请发给离婚证；未申请的，视为撤回离婚登记申请。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('fenju-zidong-lihun', '《民法典》第 1079 条',
     '夫妻一方要求离婚的，可以由有关组织进行调解或者直接向人民法院提起离婚诉讼。人民法院审理离婚案件，应当进行调解；如果感情确已破裂，调解无效的，应当准予离婚。有下列情形之一，调解无效的，应当准予离婚：（一）重婚或者与他人同居；（二）实施家庭暴力或者虐待、遗弃家庭成员；（三）有赌博、吸毒等恶习屡教不改；（四）因感情不和分居满二年；（五）其他导致夫妻感情破裂的情形。一方被宣告失踪，另一方提起离婚诉讼的，应当准予离婚。经人民法院判决不准离婚后，双方又分居满一年，一方再次提起离婚诉讼的，应当准予离婚。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('fenju-zidong-lihun', '《民法典》第 1062 条',
     '夫妻在婚姻关系存续期间所得的下列财产，为夫妻的共同财产，归夫妻共同所有：（一）工资、奖金、劳务报酬；（二）生产、经营、投资的收益；（三）知识产权的收益；（四）继承或者受赠的财产，但是本法第一千零六十三条第三项规定的除外；（五）其他应当归共同所有的财产。夫妻对共同财产，有平等的处理权。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('yanghaquan-guishu', '《民法典》第 1084 条',
     '父母与子女间的关系，不因父母离婚而消除。离婚后，子女无论由父或者母直接抚养，仍是父母双方的子女。离婚后，父母对于子女仍有抚养、教育、保护的权利和义务。离婚后，不满两周岁的子女，以由母亲直接抚养为原则。已满两周岁的子女，父母双方对抚养问题协议不成的，由人民法院根据双方的具体情况，按照最有利于未成年子女的原则判决。子女已满八周岁的，应当尊重其真实意愿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('fuzi-yanghafei', '《民法典》第 1085 条',
     '离婚后，子女由一方直接抚养的，另一方应当负担部分或者全部抚养费。负担费用的多少和期限的长短，由双方协议；协议不成的，由人民法院判决。前款规定的协议或者判决，不妨碍子女在必要时向父母任何一方提出超过协议或者判决原定数额的合理要求。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('fuzi-yanghafei', '《民法典》第 1067 条',
     '父母不履行抚养义务的，未成年子女或者不能独立生活的成年子女，有要求父母给付抚养费的权利。成年子女不履行赡养义务的，缺乏劳动能力或者生活困难的父母，有要求成年子女给付赡养费的权利。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('tanwangquan', '《民法典》第 1086 条',
     '离婚后，不直接抚养子女的父或者母，有探望子女的权利，另一方有协助的义务。行使探望权利的方式、时间由当事人协议；协议不成的，由人民法院判决。父或者母探望子女，不利于子女身心健康的，由人民法院依法中止探望；中止的事由消失后，应当恢复探望。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('tanwangquan', '《民法典》第 1084 条',
     '父母与子女间的关系，不因父母离婚而消除。离婚后，子女无论由父或者母直接抚养，仍是父母双方的子女。离婚后，父母对于子女仍有抚养、教育、保护的权利和义务。离婚后，不满两周岁的子女，以由母亲直接抚养为原则。已满两周岁的子女，父母双方对抚养问题协议不成的，由人民法院根据双方的具体情况，按照最有利于未成年子女的原则判决。子女已满八周岁的，应当尊重其真实意愿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('chugui-peichang', '《民法典》第 1091 条',
     '有下列情形之一，导致离婚的，无过错方有权请求损害赔偿：（一）重婚；（二）与他人同居；（三）实施家庭暴力；（四）虐待、遗弃家庭成员；（五）有其他重大过错。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('chugui-peichang', '《民法典》第 1087 条',
     '离婚时，夫妻的共同财产由双方协议处理；协议不成的，由人民法院根据财产的具体情况，按照照顾子女、女方和无过错方权益的原则判决。对夫或者妻在家庭土地承包经营中享有的权益等，应当依法予以保护。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('yincang-caichan', '《民法典》第 1092 条',
     '夫妻一方隐藏、转移、变卖、毁损、挥霍夫妻共同财产，或者伪造夫妻共同债务企图侵占另一方财产的，在离婚分割夫妻共同财产时，对该方可以少分或者不分。离婚后，另一方发现有上述行为的，可以向人民法院提起诉讼，请求再次分割夫妻共同财产。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('yincang-caichan', '《民法典》第 1066 条',
     '婚姻关系存续期间，有下列情形之一的，夫妻一方可以向人民法院请求分割共同财产：（一）一方有隐藏、转移、变卖、毁损、挥霍夫妻共同财产或者伪造夫妻共同债务等严重损害夫妻共同财产利益的行为；（二）一方负有法定扶养义务的人患重大疾病需要医治，另一方不同意支付相关医疗费用。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('hunqian-caichan', '《民法典》第 1063 条',
     '下列财产为夫妻一方的个人财产：（一）一方的婚前财产；（二）一方因受到人身损害获得的赔偿或者补偿；（三）遗嘱或者赠与合同中确定只归一方的财产；（四）一方专用的生活用品；（五）其他应当归一方的财产。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('hunqian-caichan', '《民法典》第 1062 条',
     '夫妻在婚姻关系存续期间所得的下列财产，为夫妻的共同财产，归夫妻共同所有：（一）工资、奖金、劳务报酬；（二）生产、经营、投资的收益；（三）知识产权的收益；（四）继承或者受赠的财产，但是本法第一千零六十三条第三项规定的除外；（五）其他应当归共同所有的财产。夫妻对共同财产，有平等的处理权。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('fangchan-jiaming', '《民法典》第 1062 条',
     '夫妻在婚姻关系存续期间所得的下列财产，为夫妻的共同财产，归夫妻共同所有：（一）工资、奖金、劳务报酬；（二）生产、经营、投资的收益；（三）知识产权的收益；（四）继承或者受赠的财产，但是本法第一千零六十三条第三项规定的除外；（五）其他应当归共同所有的财产。夫妻对共同财产，有平等的处理权。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('fangchan-jiaming', '《民法典》第 1065 条',
     '男女双方可以约定婚姻关系存续期间所得的财产以及婚前财产归各自所有、共同所有或者部分各自所有、部分共同所有。约定应当采用书面形式。没有约定或者约定不明确的，适用本法第一千零六十二条、第一千零六十三条的规定。夫妻对婚姻关系存续期间所得的财产以及婚前财产的约定，对双方具有法律约束力。夫妻对婚姻关系存续期间所得的财产约定归各自所有，夫或者妻一方对外所负的债务，相对人知道该约定的，以夫或者妻一方的个人财产清偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('fufu-caichan-xieyi', '《民法典》第 1065 条',
     '男女双方可以约定婚姻关系存续期间所得的财产以及婚前财产归各自所有、共同所有或者部分各自所有、部分共同所有。约定应当采用书面形式。没有约定或者约定不明确的，适用本法第一千零六十二条、第一千零六十三条的规定。夫妻对婚姻关系存续期间所得的财产以及婚前财产的约定，对双方具有法律约束力。夫妻对婚姻关系存续期间所得的财产约定归各自所有，夫或者妻一方对外所负的债务，相对人知道该约定的，以夫或者妻一方的个人财产清偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('fufu-caichan-xieyi', '《民法典》第 1062 条',
     '夫妻在婚姻关系存续期间所得的下列财产，为夫妻的共同财产，归夫妻共同所有：（一）工资、奖金、劳务报酬；（二）生产、经营、投资的收益；（三）知识产权的收益；（四）继承或者受赠的财产，但是本法第一千零六十三条第三项规定的除外；（五）其他应当归共同所有的财产。夫妻对共同财产，有平等的处理权。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('shanyang-laoren', '《民法典》第 1067 条',
     '父母不履行抚养义务的，未成年子女或者不能独立生活的成年子女，有要求父母给付抚养费的权利。成年子女不履行赡养义务的，缺乏劳动能力或者生活困难的父母，有要求成年子女给付赡养费的权利。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('shanyang-laoren', '《民法典》第 1069 条',
     '子女应当尊重父母的婚姻权利，不得干涉父母离婚、再婚以及婚后的生活。子女对父母的赡养义务，不因父母的婚姻关系变化而终止。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('yizhu-zenme-xie', '《民法典》第 1134 条',
     '自书遗嘱由遗嘱人亲笔书写，签名，注明年、月、日。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('yizhu-zenme-xie', '《民法典》第 1136 条',
     '打印遗嘱应当有两个以上见证人在场见证。遗嘱人和见证人应当在遗嘱每一页签名，注明年、月、日。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('yizhu-zenme-xie', '《民法典》第 1133 条',
     '自然人可以依照本法规定立遗嘱处分个人财产，并可以指定遗嘱执行人。自然人可以立遗嘱将个人财产指定由法定继承人中的一人或者数人继承。自然人可以立遗嘱将个人财产赠与国家、集体或者法定继承人以外的组织、个人。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 3),
    ('fading-jicheng-shunxu', '《民法典》第 1127 条',
     '遗产按照下列顺序继承：（一）第一顺序：配偶、子女、父母；（二）第二顺序：兄弟姐妹、祖父母、外祖父母。继承开始后，由第一顺序继承人继承，第二顺序继承人不继承；没有第一顺序继承人继承的，由第二顺序继承人继承。本编所称子女，包括婚生子女、非婚生子女、养子女和有扶养关系的继子女。本编所称父母，包括生父母、养父母和有扶养关系的继父母。本编所称兄弟姐妹，包括同父母的兄弟姐妹、同父异母或者同母异父的兄弟姐妹、养兄弟姐妹、有扶养关系的继兄弟姐妹。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('fading-jicheng-shunxu', '《民法典》第 1130 条',
     '同一顺序继承人继承遗产的份额，一般应当均等。对生活有特殊困难又缺乏劳动能力的继承人，分配遗产时，应当予以照顾。对被继承人尽了主要扶养义务或者与被继承人共同生活的继承人，分配遗产时，可以多分。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('fading-jicheng-shunxu', '《民法典》第 1123 条',
     '继承开始后，按照法定继承办理；有遗嘱的，按照遗嘱继承或者遗赠办理；有遗赠扶养协议的，按照协议办理。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 3),
    ('zaihun-jicheng', '《民法典》第 1069 条',
     '子女应当尊重父母的婚姻权利，不得干涉父母离婚、再婚以及婚后的生活。子女对父母的赡养义务，不因父母的婚姻关系变化而终止。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('zaihun-jicheng', '《民法典》第 1127 条',
     '遗产按照下列顺序继承：（一）第一顺序：配偶、子女、父母；（二）第二顺序：兄弟姐妹、祖父母、外祖父母。继承开始后，由第一顺序继承人继承，第二顺序继承人不继承；没有第一顺序继承人继承的，由第二顺序继承人继承。本编所称子女，包括婚生子女、非婚生子女、养子女和有扶养关系的继子女。本编所称父母，包括生父母、养父母和有扶养关系的继父母。本编所称兄弟姐妹，包括同父母的兄弟姐妹、同父异母或者同母异父的兄弟姐妹、养兄弟姐妹、有扶养关系的继兄弟姐妹。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('feihunsheng-zinv', '《民法典》第 1071 条',
     '非婚生子女享有与婚生子女同等的权利，任何组织或者个人不得加以危害和歧视。不直接抚养非婚生子女的生父或者生母，应当负担未成年子女或者不能独立生活的成年子女的抚养费。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('feihunsheng-zinv', '《民法典》第 1127 条',
     '遗产按照下列顺序继承：（一）第一顺序：配偶、子女、父母；（二）第二顺序：兄弟姐妹、祖父母、外祖父母。继承开始后，由第一顺序继承人继承，第二顺序继承人不继承；没有第一顺序继承人继承的，由第二顺序继承人继承。本编所称子女，包括婚生子女、非婚生子女、养子女和有扶养关系的继子女。本编所称父母，包括生父母、养父母和有扶养关系的继父母。本编所称兄弟姐妹，包括同父母的兄弟姐妹、同父异母或者同母异父的兄弟姐妹、养兄弟姐妹、有扶养关系的继兄弟姐妹。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('dianche-pengzhuang', '《道路交通安全法》第 76 条',
     '机动车发生交通事故造成人身伤亡、财产损失的，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿；不足的部分，按照下列规定承担赔偿责任：（一）机动车之间发生交通事故的，由有过错的一方承担赔偿责任；双方都有过错的，按照各自过错的比例分担责任。（二）机动车与非机动车驾驶人、行人之间发生交通事故，非机动车驾驶人、行人没有过错的，由机动车一方承担赔偿责任；有证据证明非机动车驾驶人、行人有过错的，根据过错程度适当减轻机动车一方的赔偿责任；机动车一方没有过错的，承担不超过百分之十的赔偿责任。交通事故的损失是由非机动车驾驶人、行人故意碰撞机动车造成的，机动车一方不承担赔偿责任。',
     'https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202307/t20230710_3158807.html', 1),
    ('jiuche-zheren', '《民法典》第 1209 条',
     '因租赁、借用等情形机动车所有人、管理人与使用人不是同一人时，发生交通事故造成损害，属于该机动车一方责任的，由机动车使用人承担赔偿责任；机动车所有人、管理人对损害的发生有过错的，承担相应的赔偿责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('jiuche-zheren', '《民法典》第 1213 条',
     '机动车发生交通事故造成损害，属于该机动车一方责任的，先由承保机动车强制保险的保险人在强制保险责任限额范围内予以赔偿；不足部分，由承保机动车商业保险的保险人按照保险合同的约定予以赔偿；仍然不足或者没有投保机动车商业保险的，由侵权人赔偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('shigu-peichang', '《民法典》第 1179 条',
     '侵害他人造成人身损害的，应当赔偿医疗费、护理费、交通费、营养费、住院伙食补助费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿辅助器具费和残疾赔偿金；造成死亡的，还应当赔偿丧葬费和死亡赔偿金。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('shigu-peichang', '《民法典》第 1213 条',
     '机动车发生交通事故造成损害，属于该机动车一方责任的，先由承保机动车强制保险的保险人在强制保险责任限额范围内予以赔偿；不足部分，由承保机动车商业保险的保险人按照保险合同的约定予以赔偿；仍然不足或者没有投保机动车商业保险的，由侵权人赔偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('jiujia-tongzhuo', '《民法典》第 1165 条',
     '行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。依照法律规定推定行为人有过错，其不能证明自己没有过错的，应当承担侵权责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('jiujia-tongzhuo', '《民法典》第 1173 条',
     '被侵权人对同一损害的发生或者扩大有过错的，可以减轻侵权人的责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('jiujia-chengke', '《道路交通安全法》第 91 条',
     '饮酒后驾驶机动车的，处暂扣六个月机动车驾驶证，并处一千元以上二千元以下罚款。因饮酒后驾驶机动车被处罚，再次饮酒后驾驶机动车的，处十日以下拘留，并处一千元以上二千元以下罚款，吊销机动车驾驶证。醉酒驾驶机动车的，由公安机关交通管理部门约束至酒醒，吊销机动车驾驶证，依法追究刑事责任；五年内不得重新取得机动车驾驶证。',
     'https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202307/t20230710_3158807.html', 1);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('jiujia-chengke', '《道路交通安全法》第 22 条',
     '机动车驾驶人应当遵守道路交通安全法律、法规的规定，按照操作规范安全驾驶、文明驾驶。饮酒、服用国家管制的精神药品或者麻醉药品，或者患有妨碍安全驾驶机动车的疾病，或者过度疲劳影响安全驾驶的，不得驾驶机动车。任何人不得强迫、指使、纵容驾驶人违反道路交通安全法律、法规和机动车安全驾驶要求驾驶机动车。',
     'https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202307/t20230710_3158807.html', 2),
    ('chuhongdeng-bei-zhuang', '《道路交通安全法》第 76 条',
     '机动车发生交通事故造成人身伤亡、财产损失的，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿；不足的部分，按照下列规定承担赔偿责任：（一）机动车之间发生交通事故的，由有过错的一方承担赔偿责任；双方都有过错的，按照各自过错的比例分担责任。（二）机动车与非机动车驾驶人、行人之间发生交通事故，非机动车驾驶人、行人没有过错的，由机动车一方承担赔偿责任；有证据证明非机动车驾驶人、行人有过错的，根据过错程度适当减轻机动车一方的赔偿责任；机动车一方没有过错的，承担不超过百分之十的赔偿责任。交通事故的损失是由非机动车驾驶人、行人故意碰撞机动车造成的，机动车一方不承担赔偿责任。',
     'https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202307/t20230710_3158807.html', 1),
    ('chuhongdeng-bei-zhuang', '《民法典》第 1213 条',
     '机动车发生交通事故造成损害，属于该机动车一方责任的，先由承保机动车强制保险的保险人在强制保险责任限额范围内予以赔偿；不足部分，由承保机动车商业保险的保险人按照保险合同的约定予以赔偿；仍然不足或者没有投保机动车商业保险的，由侵权人赔偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('chemai-weiguohu', '《民法典》第 1210 条',
     '当事人之间已经以买卖或者其他方式转让并交付机动车但是未办理登记，发生交通事故造成损害，属于该机动车一方责任的，由受让人承担赔偿责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('chemai-weiguohu', '《民法典》第 1213 条',
     '机动车发生交通事故造成损害，属于该机动车一方责任的，先由承保机动车强制保险的保险人在强制保险责任限额范围内予以赔偿；不足部分，由承保机动车商业保险的保险人按照保险合同的约定予以赔偿；仍然不足或者没有投保机动车商业保险的，由侵权人赔偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('shigu-taoyi', '《民法典》第 1216 条',
     '机动车驾驶人发生交通事故后逃逸，该机动车参加强制保险的，由保险人在机动车强制保险责任限额范围内予以赔偿；机动车不明、该机动车未参加强制保险或者抢救费用超过机动车强制保险责任限额，需要支付被侵权人人身伤亡的抢救、丧葬等费用的，由道路交通事故社会救助基金垫付。道路交通事故社会救助基金垫付后，其管理机构有权向交通事故责任人追偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('shigu-taoyi', '《道路交通安全法》第 101 条',
     '违反道路交通安全法律、法规的规定，发生重大交通事故，构成犯罪的，依法追究刑事责任，并由公安机关交通管理部门吊销机动车驾驶证。造成交通事故后逃逸的，由公安机关交通管理部门吊销机动车驾驶证，且终生不得重新取得机动车驾驶证。',
     'https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202307/t20230710_3158807.html', 2),
    ('pengche-gaosu', '《道路交通安全法》第 70 条',
     '在道路上发生交通事故，车辆驾驶人应当立即停车，保护现场；造成人身伤亡的，车辆驾驶人应当立即抢救受伤人员，并迅速报告执勤的交通警察或者公安机关交通管理部门。因抢救受伤人员变动现场的，应当标明位置。乘车人、过往车辆驾驶人、过往行人应当予以协助。在道路上发生交通事故，未造成人身伤亡，当事人对事实及成因无争议的，可以即行撤离现场，恢复交通，自行协商处理损害赔偿事宜；不即行撤离现场的，应当迅速报告执勤的交通警察或者公安机关交通管理部门。在道路上发生交通事故，仅造成轻微财产损失，并且基本事实清楚的，当事人应当先撤离现场再进行协商处理。',
     'https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202307/t20230710_3158807.html', 1),
    ('pengche-gaosu', '《道路交通安全法》第 22 条',
     '机动车驾驶人应当遵守道路交通安全法律、法规的规定，按照操作规范安全驾驶、文明驾驶。饮酒、服用国家管制的精神药品或者麻醉药品，或者患有妨碍安全驾驶机动车的疾病，或者过度疲劳影响安全驾驶的，不得驾驶机动车。任何人不得强迫、指使、纵容驾驶人违反道路交通安全法律、法规和机动车安全驾驶要求驾驶机动车。',
     'https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202307/t20230710_3158807.html', 2),
    ('danche-zhuang-ren', '《民法典》第 1165 条',
     '行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。依照法律规定推定行为人有过错，其不能证明自己没有过错的，应当承担侵权责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('danche-zhuang-ren', '《民法典》第 1179 条',
     '侵害他人造成人身损害的，应当赔偿医疗费、护理费、交通费、营养费、住院伙食补助费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿辅助器具费和残疾赔偿金；造成死亡的，还应当赔偿丧葬费和死亡赔偿金。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('pinche-shigu', '《民法典》第 1217 条',
     '非营运机动车发生交通事故造成无偿搭乘人损害，属于该机动车一方责任的，应当减轻其赔偿责任，但是机动车使用人有故意或者重大过失的除外。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('pinche-shigu', '《民法典》第 1213 条',
     '机动车发生交通事故造成损害，属于该机动车一方责任的，先由承保机动车强制保险的保险人在强制保险责任限额范围内予以赔偿；不足部分，由承保机动车商业保险的保险人按照保险合同的约定予以赔偿；仍然不足或者没有投保机动车商业保险的，由侵权人赔偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('tou-kaiche', '《民法典》第 1212 条',
     '未经允许驾驶他人机动车，发生交通事故造成损害，属于该机动车一方责任的，由机动车使用人承担赔偿责任；机动车所有人、管理人对损害的发生有过错的，承担相应的赔偿责任，但是本章另有规定的除外。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('tou-kaiche', '《民法典》第 1209 条',
     '因租赁、借用等情形机动车所有人、管理人与使用人不是同一人时，发生交通事故造成损害，属于该机动车一方责任的，由机动车使用人承担赔偿责任；机动车所有人、管理人对损害的发生有过错的，承担相应的赔偿责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('guakao-shigu', '《民法典》第 1211 条',
     '以挂靠形式从事道路运输经营活动的机动车，发生交通事故造成损害，属于该机动车一方责任的，由挂靠人和被挂靠人承担连带责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('guakao-shigu', '《民法典》第 1213 条',
     '机动车发生交通事故造成损害，属于该机动车一方责任的，先由承保机动车强制保险的保险人在强制保险责任限额范围内予以赔偿；不足部分，由承保机动车商业保险的保险人按照保险合同的约定予以赔偿；仍然不足或者没有投保机动车商业保险的，由侵权人赔偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('dingjie-bufu', '《道路交通安全法》第 73 条',
     '公安机关交通管理部门应当根据交通事故现场勘验、检查、调查情况和有关的检验、鉴定结论，及时制作交通事故认定书，作为处理交通事故的证据。交通事故认定书应当载明交通事故的基本事实、成因和当事人的责任，并送达当事人。',
     'https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202307/t20230710_3158807.html', 1),
    ('dingjie-bufu', '《民法典》第 1165 条',
     '行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。依照法律规定推定行为人有过错，其不能证明自己没有过错的，应当承担侵权责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('wangyueche-chengke', '《民法典》第 1179 条',
     '侵害他人造成人身损害的，应当赔偿医疗费、护理费、交通费、营养费、住院伙食补助费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿辅助器具费和残疾赔偿金；造成死亡的，还应当赔偿丧葬费和死亡赔偿金。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('wangyueche-chengke', '《民法典》第 1213 条',
     '机动车发生交通事故造成损害，属于该机动车一方责任的，先由承保机动车强制保险的保险人在强制保险责任限额范围内予以赔偿；不足部分，由承保机动车商业保险的保险人按照保险合同的约定予以赔偿；仍然不足或者没有投保机动车商业保险的，由侵权人赔偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('wu-baoxian-shigu', '《民法典》第 1213 条',
     '机动车发生交通事故造成损害，属于该机动车一方责任的，先由承保机动车强制保险的保险人在强制保险责任限额范围内予以赔偿；不足部分，由承保机动车商业保险的保险人按照保险合同的约定予以赔偿；仍然不足或者没有投保机动车商业保险的，由侵权人赔偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('wu-baoxian-shigu', '《民法典》第 1208 条',
     '机动车发生交通事故造成损害的，依照道路交通安全法律和本法的有关规定承担赔偿责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('chedun-zhao-buduoren', '《道路交通安全法》第 70 条',
     '在道路上发生交通事故，车辆驾驶人应当立即停车，保护现场；造成人身伤亡的，车辆驾驶人应当立即抢救受伤人员，并迅速报告执勤的交通警察或者公安机关交通管理部门。因抢救受伤人员变动现场的，应当标明位置。乘车人、过往车辆驾驶人、过往行人应当予以协助。在道路上发生交通事故，未造成人身伤亡，当事人对事实及成因无争议的，可以即行撤离现场，恢复交通，自行协商处理损害赔偿事宜；不即行撤离现场的，应当迅速报告执勤的交通警察或者公安机关交通管理部门。在道路上发生交通事故，仅造成轻微财产损失，并且基本事实清楚的，当事人应当先撤离现场再进行协商处理。',
     'https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202307/t20230710_3158807.html', 1),
    ('chedun-zhao-buduoren', '《民法典》第 1165 条',
     '行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。依照法律规定推定行为人有过错，其不能证明自己没有过错的，应当承担侵权责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('jiazhao-shigu', '《道路交通安全法》第 99 条',
     '有下列行为之一的，由公安机关交通管理部门处二百元以上二千元以下罚款：（一）未取得机动车驾驶证、机动车驾驶证被吊销或者机动车驾驶证被暂扣期间驾驶机动车的；（二）将机动车交由未取得机动车驾驶证或者机动车驾驶证被吊销、暂扣的人驾驶的；（三）造成交通事故后逃逸，尚不构成犯罪的；（四）机动车行驶超过规定时速百分之五十的；（五）强迫机动车驾驶人违反道路交通安全法律、法规和机动车安全驾驶要求驾驶机动车，造成交通事故，尚不构成犯罪的；（六）违反交通管制的规定强行通行，不听劝阻的；（七）故意损毁、移动、涂改交通设施，造成危害后果，尚不构成犯罪的；（八）非法拦截、扣留机动车辆，不听劝阻，造成交通严重阻塞或者较大财产损失的。行为人有前款第二项、第四项情形之一的，可以并处吊销机动车驾驶证；有第一项、第三项、第五项至第八项情形之一的，可以并处十五日以下拘留。',
     'https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202307/t20230710_3158807.html', 1),
    ('jiazhao-shigu', '《民法典》第 1209 条',
     '因租赁、借用等情形机动车所有人、管理人与使用人不是同一人时，发生交通事故造成损害，属于该机动车一方责任的，由机动车使用人承担赔偿责任；机动车所有人、管理人对损害的发生有过错的，承担相应的赔偿责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('renshang-xiangmu', '《民法典》第 1179 条',
     '侵害他人造成人身损害的，应当赔偿医疗费、护理费、交通费、营养费、住院伙食补助费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿辅助器具费和残疾赔偿金；造成死亡的，还应当赔偿丧葬费和死亡赔偿金。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('renshang-xiangmu', '《民法典》第 1183 条',
     '侵害自然人人身权益造成严重精神损害的，被侵权人有权请求精神损害赔偿。因故意或者重大过失侵害自然人具有人身意义的特定物造成严重精神损害的，被侵权人有权请求精神损害赔偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('jingshen-sunhai', '《民法典》第 1183 条',
     '侵害自然人人身权益造成严重精神损害的，被侵权人有权请求精神损害赔偿。因故意或者重大过失侵害自然人具有人身意义的特定物造成严重精神损害的，被侵权人有权请求精神损害赔偿。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('jingshen-sunhai', '《民法典》第 1179 条',
     '侵害他人造成人身损害的，应当赔偿医疗费、护理费、交通费、营养费、住院伙食补助费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿辅助器具费和残疾赔偿金；造成死亡的，还应当赔偿丧葬费和死亡赔偿金。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('loudong-loushui', '《民法典》第 296 条',
     '不动产权利人因用水、排水、通行、铺设管线等利用相邻不动产的，应当尽量避免对相邻的不动产权利人造成损害。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('loudong-loushui', '《民法典》第 1165 条',
     '行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。依照法律规定推定行为人有过错，其不能证明自己没有过错的，应当承担侵权责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('loudong-loushui', '《民法典》第 288 条',
     '不动产的相邻权利人应当按照有利生产、方便生活、团结互助、公平合理的原则，正确处理相邻关系。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 3),
    ('caiguang-zhedang', '《民法典》第 293 条',
     '建造建筑物，不得违反国家有关工程建设标准，不得妨碍相邻建筑物的通风、采光和日照。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('caiguang-zhedang', '《民法典》第 288 条',
     '不动产的相邻权利人应当按照有利生产、方便生活、团结互助、公平合理的原则，正确处理相邻关系。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('guangchang-wu', '《噪声污染防治法》第 64 条',
     '禁止在噪声敏感建筑物集中区域使用高音广播喇叭，但紧急情况以及地方人民政府规定的特殊情形除外。在街道、广场、公园等公共场所组织或者开展娱乐、健身等活动，应当遵守公共场所管理者有关活动区域、时段、音量等规定，采取有效措施，防止噪声污染；不得违反规定使用音响器材产生过大音量。公共场所管理者应当合理规定娱乐、健身等活动的区域、时段、音量，可以采取设置噪声自动监测和显示设施等措施加强管理。',
     'http://www.npc.gov.cn/c2/c30834/202112/t20211224_315601.html', 1),
    ('guangchang-wu', '《治安管理处罚法》第 88 条',
     '违反关于社会生活噪声污染防治的法律法规规定，产生社会生活噪声，经基层群众性自治组织、业主委员会、物业服务人、有关部门依法劝阻、调解和处理未能制止，继续干扰他人正常生活、工作和学习的，处五日以下拘留或者一千元以下罚款；情节严重的，处五日以上十日以下拘留，可以并处一千元以下罚款。',
     'http://www.npc.gov.cn/c2/c30834/202506/t20250627_446254.html', 2),
    ('yantaom-zaoyin', '《治安管理处罚法》第 88 条',
     '违反关于社会生活噪声污染防治的法律法规规定，产生社会生活噪声，经基层群众性自治组织、业主委员会、物业服务人、有关部门依法劝阻、调解和处理未能制止，继续干扰他人正常生活、工作和学习的，处五日以下拘留或者一千元以下罚款；情节严重的，处五日以上十日以下拘留，可以并处一千元以下罚款。',
     'http://www.npc.gov.cn/c2/c30834/202506/t20250627_446254.html', 1),
    ('yantaom-zaoyin', '《民法典》第 294 条',
     '不动产权利人不得违反国家规定弃置固体废物，排放大气污染物、水污染物、土壤污染物、噪声、光辐射、电磁辐射等有害物质。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('kongtiao-dishui', '《民法典》第 296 条',
     '不动产权利人因用水、排水、通行、铺设管线等利用相邻不动产的，应当尽量避免对相邻的不动产权利人造成损害。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('kongtiao-dishui', '《民法典》第 294 条',
     '不动产权利人不得违反国家规定弃置固体废物，排放大气污染物、水污染物、土壤污染物、噪声、光辐射、电磁辐射等有害物质。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('loudao-duiwu', '《民法典》第 286 条',
     '业主应当遵守法律、法规以及管理规约，相关行为应当符合节约资源、保护生态环境的要求。对于物业服务企业或者其他管理人执行政府依法实施的应急处置措施和其他管理措施，业主应当依法予以配合。业主大会或者业主委员会，对任意弃置垃圾、排放污染物或者噪声、违反规定饲养动物、违章搭建、侵占通道、拒付物业费等损害他人合法权益的行为，有权依照法律、法规以及管理规约，请求行为人停止侵害、排除妨碍、消除危险、恢复原状、赔偿损失。业主或者其他行为人拒不履行相关义务的，有关当事人可以向有关行政主管部门报告或者投诉，有关行政主管部门应当依法处理。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('loudao-duiwu', '《民法典》第 272 条',
     '业主对其建筑物专有部分享有占有、使用、收益和处分的权利。业主行使权利不得危及建筑物的安全，不得损害其他业主的合法权益。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('zhuzhai-gai-minfang', '《民法典》第 279 条',
     '业主不得违反法律、法规以及管理规约，将住宅改变为经营性用房。业主将住宅改变为经营性用房的，除遵守法律、法规以及管理规约外，应当经有利害关系的业主一致同意。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('zhuzhai-gai-minfang', '《民法典》第 286 条',
     '业主应当遵守法律、法规以及管理规约，相关行为应当符合节约资源、保护生态环境的要求。对于物业服务企业或者其他管理人执行政府依法实施的应急处置措施和其他管理措施，业主应当依法予以配合。业主大会或者业主委员会，对任意弃置垃圾、排放污染物或者噪声、违反规定饲养动物、违章搭建、侵占通道、拒付物业费等损害他人合法权益的行为，有权依照法律、法规以及管理规约，请求行为人停止侵害、排除妨碍、消除危险、恢复原状、赔偿损失。业主或者其他行为人拒不履行相关义务的，有关当事人可以向有关行政主管部门报告或者投诉，有关行政主管部门应当依法处理。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('wuyefei-gaijiao', '《民法典》第 286 条',
     '业主应当遵守法律、法规以及管理规约，相关行为应当符合节约资源、保护生态环境的要求。对于物业服务企业或者其他管理人执行政府依法实施的应急处置措施和其他管理措施，业主应当依法予以配合。业主大会或者业主委员会，对任意弃置垃圾、排放污染物或者噪声、违反规定饲养动物、违章搭建、侵占通道、拒付物业费等损害他人合法权益的行为，有权依照法律、法规以及管理规约，请求行为人停止侵害、排除妨碍、消除危险、恢复原状、赔偿损失。业主或者其他行为人拒不履行相关义务的，有关当事人可以向有关行政主管部门报告或者投诉，有关行政主管部门应当依法处理。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('wuyefei-gaijiao', '《民法典》第 282 条',
     '建设单位、物业服务企业或者其他管理人等利用业主的共有部分产生的收入，在扣除合理成本之后，属于业主共有。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('dianti-guanggao', '《民法典》第 282 条',
     '建设单位、物业服务企业或者其他管理人等利用业主的共有部分产生的收入，在扣除合理成本之后，属于业主共有。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('dianti-guanggao', '《民法典》第 274 条',
     '建筑区划内的道路，属于业主共有，但是属于城镇公共道路的除外。建筑区划内的绿地，属于业主共有，但是属于城镇公共绿地或者明示属于个人的除外。建筑区划内的其他公共场所、公用设施和物业服务用房，属于业主共有。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('chewei-gui-shui', '《民法典》第 275 条',
     '建筑区划内，规划用于停放汽车的车位、车库的归属，由当事人通过出售、附赠或者出租等方式约定。占用业主共有的道路或者其他场地用于停放汽车的车位，属于业主共有。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('chewei-gui-shui', '《民法典》第 282 条',
     '建设单位、物业服务企业或者其他管理人等利用业主的共有部分产生的收入，在扣除合理成本之后，属于业主共有。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('chai-chengzhongqiang', '《民法典》第 272 条',
     '业主对其建筑物专有部分享有占有、使用、收益和处分的权利。业主行使权利不得危及建筑物的安全，不得损害其他业主的合法权益。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('chai-chengzhongqiang', '《民法典》第 1165 条',
     '行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。依照法律规定推定行为人有过错，其不能证明自己没有过错的，应当承担侵权责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('gou-bu-shuansheng', '《民法典》第 1246 条',
     '违反管理规定，未对动物采取安全措施造成他人损害的，动物饲养人或者管理人应当承担侵权责任；但是，能够证明损害是因被侵权人故意造成的，可以减轻责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('gou-bu-shuansheng', '《民法典》第 1245 条',
     '饲养的动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任；但是，能够证明损害是因被侵权人故意或者重大过失造成的，可以不承担或者减轻责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('gou-bu-shuansheng', '《治安管理处罚法》第 89 条',
     '饲养动物，干扰他人正常生活的，处警告；警告后不改正的，或者放任动物恐吓他人的，处一千元以下罚款。违反有关法律、法规、规章规定，出售、饲养烈性犬等危险动物的，处警告；警告后不改正的，或者致使动物伤害他人的，处五日以下拘留或者一千元以下罚款；情节较重的，处五日以上十日以下拘留。未对动物采取安全措施，致使动物伤害他人的，处一千元以下罚款；情节较重的，处五日以上十日以下拘留。驱使动物伤害他人的，依照本法第五十一条的规定处罚。',
     'http://www.npc.gov.cn/c2/c30834/202506/t20250627_446254.html', 3),
    ('chongwu-raomin', '《治安管理处罚法》第 89 条',
     '饲养动物，干扰他人正常生活的，处警告；警告后不改正的，或者放任动物恐吓他人的，处一千元以下罚款。违反有关法律、法规、规章规定，出售、饲养烈性犬等危险动物的，处警告；警告后不改正的，或者致使动物伤害他人的，处五日以下拘留或者一千元以下罚款；情节较重的，处五日以上十日以下拘留。未对动物采取安全措施，致使动物伤害他人的，处一千元以下罚款；情节较重的，处五日以上十日以下拘留。驱使动物伤害他人的，依照本法第五十一条的规定处罚。',
     'http://www.npc.gov.cn/c2/c30834/202506/t20250627_446254.html', 1),
    ('chongwu-raomin', '《民法典》第 1251 条',
     '饲养动物应当遵守法律法规，尊重社会公德，不得妨碍他人生活。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('qunli-ruzhu', '《民法典》第 1024 条',
     '民事主体享有名誉权。任何组织或者个人不得以侮辱、诽谤等方式侵害他人的名誉权。名誉是对民事主体的品德、声望、才能、信用等的社会评价。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('qunli-ruzhu', '《民法典》第 1000 条',
     '行为人因侵害人格权承担消除影响、恢复名誉、赔礼道歉等民事责任的，应当与行为的具体方式和造成的影响范围相当。行为人拒不承担前款规定的民事责任的，人民法院可以采取在报刊、网络等媒体上发布公告或者公布生效裁判文书等方式执行，产生的费用由行为人负担。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('qunli-ruzhu', '《治安管理处罚法》第 50 条',
     '有下列行为之一的，处五日以下拘留或者一千元以下罚款；情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款：（一）写恐吓信或者以其他方法威胁他人人身安全的；（二）公然侮辱他人或者捏造事实诽谤他人的；（三）捏造事实诬告陷害他人，企图使他人受到刑事追究或者受到治安管理处罚的；（四）对证人及其近亲属进行威胁、侮辱、殴打或者打击报复的；（五）多次发送淫秽、侮辱、恐吓等信息或者采取滋扰、纠缠、跟踪等方法，干扰他人正常生活的；（六）偷窥、偷拍、窃听、散布他人隐私的。有前款第五项规定的滋扰、纠缠、跟踪行为的，除依照前款规定给予处罚外，经公安机关负责人批准，可以责令其一定期限内禁止接触被侵害人。对违反禁止接触规定的，处五日以上十日以下拘留，可以并处一千元以下罚款。',
     'http://www.npc.gov.cn/c2/c30834/202506/t20250627_446254.html', 3),
    ('mingyu-gongshi', '《民法典》第 1024 条',
     '民事主体享有名誉权。任何组织或者个人不得以侮辱、诽谤等方式侵害他人的名誉权。名誉是对民事主体的品德、声望、才能、信用等的社会评价。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('mingyu-gongshi', '《民法典》第 1025 条',
     '行为人为公共利益实施新闻报道、舆论监督等行为，影响他人名誉的，不承担民事责任，但是有下列情形之一的除外：（一）捏造、歪曲事实；（二）对他人提供的严重失实内容未尽到合理核实义务；（三）使用侮辱性言辞等贬损他人名誉。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('mingyu-gongshi', '《治安管理处罚法》第 50 条',
     '有下列行为之一的，处五日以下拘留或者一千元以下罚款；情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款：（一）写恐吓信或者以其他方法威胁他人人身安全的；（二）公然侮辱他人或者捏造事实诽谤他人的；（三）捏造事实诬告陷害他人，企图使他人受到刑事追究或者受到治安管理处罚的；（四）对证人及其近亲属进行威胁、侮辱、殴打或者打击报复的；（五）多次发送淫秽、侮辱、恐吓等信息或者采取滋扰、纠缠、跟踪等方法，干扰他人正常生活的；（六）偷窥、偷拍、窃听、散布他人隐私的。有前款第五项规定的滋扰、纠缠、跟踪行为的，除依照前款规定给予处罚外，经公安机关负责人批准，可以责令其一定期限内禁止接触被侵害人。对违反禁止接触规定的，处五日以上十日以下拘留，可以并处一千元以下罚款。',
     'http://www.npc.gov.cn/c2/c30834/202506/t20250627_446254.html', 3),
    ('yaoyan-pianju', '《治安管理处罚法》第 29 条',
     '有下列行为之一的，处五日以上十日以下拘留，可以并处一千元以下罚款；情节较轻的，处五日以下拘留或者一千元以下罚款：（一）故意散布谣言，谎报险情、疫情、灾情、警情或者以其他方法故意扰乱公共秩序的；（二）投放虚假的爆炸性、毒害性、放射性、腐蚀性物质或者传染病病原体等危险物质扰乱公共秩序的；（三）扬言实施放火、爆炸、投放危险物质等危害公共安全犯罪行为扰乱公共秩序的。',
     'http://www.npc.gov.cn/c2/c30834/202506/t20250627_446254.html', 1),
    ('yaoyan-pianju', '《民法典》第 1025 条',
     '行为人为公共利益实施新闻报道、舆论监督等行为，影响他人名誉的，不承担民事责任，但是有下列情形之一的除外：（一）捏造、歪曲事实；（二）对他人提供的严重失实内容未尽到合理核实义务；（三）使用侮辱性言辞等贬损他人名誉。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('paizhao-chuanbo', '《民法典》第 1032 条',
     '自然人享有隐私权。任何组织或者个人不得以刺探、侵扰、泄露、公开等方式侵害他人的隐私权。隐私是自然人的私人生活安宁和不愿为他人知晓的私密空间、私密活动、私密信息。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('paizhao-chuanbo', '《民法典》第 1033 条',
     '除法律另有规定或者权利人明确同意外，任何组织或者个人不得实施下列行为：（一）以电话、短信、即时通讯工具、电子邮件、传单等方式侵扰他人的私人生活安宁；（二）进入、拍摄、窥视他人的住宅、宾馆房间等私密空间；（三）拍摄、窥视、窃听、公开他人的私密活动；（四）拍摄、窥视他人身体的私密部位；（五）处理他人的私密信息；（六）以其他方式侵害他人的隐私权。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('paizhao-chuanbo', '《治安管理处罚法》第 50 条',
     '有下列行为之一的，处五日以下拘留或者一千元以下罚款；情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款：（一）写恐吓信或者以其他方法威胁他人人身安全的；（二）公然侮辱他人或者捏造事实诽谤他人的；（三）捏造事实诬告陷害他人，企图使他人受到刑事追究或者受到治安管理处罚的；（四）对证人及其近亲属进行威胁、侮辱、殴打或者打击报复的；（五）多次发送淫秽、侮辱、恐吓等信息或者采取滋扰、纠缠、跟踪等方法，干扰他人正常生活的；（六）偷窥、偷拍、窃听、散布他人隐私的。有前款第五项规定的滋扰、纠缠、跟踪行为的，除依照前款规定给予处罚外，经公安机关负责人批准，可以责令其一定期限内禁止接触被侵害人。对违反禁止接触规定的，处五日以上十日以下拘留，可以并处一千元以下罚款。',
     'http://www.npc.gov.cn/c2/c30834/202506/t20250627_446254.html', 3);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('gao-kong-pao-wu-zeren', '《民法典》第 1254 条',
     '禁止从建筑物中抛掷物品。从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害的，由侵权人依法承担侵权责任；经调查难以确定具体侵权人的，除能够证明自己不是侵权人的外，由可能加害的建筑物使用人给予补偿。可能加害的建筑物使用人补偿后，有权向侵权人追偿。物业服务企业等建筑物管理人应当采取必要的安全保障措施防止前款规定情形的发生；未采取必要的安全保障措施的，应当依法承担未履行安全保障义务的侵权责任。发生本条第一款规定的情形的，公安等机关应当依法及时调查，查清责任人。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('gao-kong-pao-wu-zeren', '《治安管理处罚法》第 43 条',
     '有下列行为之一的，处五日以下拘留或者一千元以下罚款；情节严重的，处十日以上十五日以下拘留，可以并处一千元以下罚款：（一）未经批准，安装、使用电网的，或者安装、使用电网不符合安全规定的；（二）在车辆、行人通行的地方施工，对沟井坎穴不设覆盖物、防围和警示标志的，或者故意损毁、移动覆盖物、防围和警示标志的；（三）盗窃、损毁路面井盖、照明等公共设施的；（四）违反有关法律法规规定，升放携带明火的升空物体，有发生火灾事故危险，不听劝阻的；（五）从建筑物或者其他高空抛掷物品，有危害他人人身安全、公私财产安全或者公共安全危险的。',
     'http://www.npc.gov.cn/c2/c30834/202506/t20250627_446254.html', 2),
    ('menshi-sheixiangtou', '《民法典》第 1032 条',
     '自然人享有隐私权。任何组织或者个人不得以刺探、侵扰、泄露、公开等方式侵害他人的隐私权。隐私是自然人的私人生活安宁和不愿为他人知晓的私密空间、私密活动、私密信息。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('menshi-sheixiangtou', '《民法典》第 1033 条',
     '除法律另有规定或者权利人明确同意外，任何组织或者个人不得实施下列行为：（一）以电话、短信、即时通讯工具、电子邮件、传单等方式侵扰他人的私人生活安宁；（二）进入、拍摄、窥视他人的住宅、宾馆房间等私密空间；（三）拍摄、窥视、窃听、公开他人的私密活动；（四）拍摄、窥视他人身体的私密部位；（五）处理他人的私密信息；（六）以其他方式侵害他人的隐私权。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('menshi-sheixiangtou', '《民法典》第 288 条',
     '不动产的相邻权利人应当按照有利生产、方便生活、团结互助、公平合理的原则，正确处理相邻关系。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 3),
    ('loudong-chaozhu', '《噪声污染防治法》第 66 条',
     '对已竣工交付使用的住宅楼、商铺、办公楼等建筑物进行室内装修活动，应当按照规定限定作业时间，采取有效措施，防止、减轻噪声污染。',
     'http://www.npc.gov.cn/c2/c30834/202112/t20211224_315601.html', 1),
    ('loudong-chaozhu', '《民法典》第 288 条',
     '不动产的相邻权利人应当按照有利生产、方便生活、团结互助、公平合理的原则，正确处理相邻关系。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('wangluo-zaoyao', '《民法典》第 1024 条',
     '民事主体享有名誉权。任何组织或者个人不得以侮辱、诽谤等方式侵害他人的名誉权。名誉是对民事主体的品德、声望、才能、信用等的社会评价。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('wangluo-zaoyao', '《民法典》第 1195 条',
     '网络用户利用网络服务实施侵权行为的，权利人有权通知网络服务提供者采取删除、屏蔽、断开链接等必要措施。通知应当包括构成侵权的初步证据及权利人的真实身份信息。网络服务提供者接到通知后，应当及时将该通知转送相关网络用户，并根据构成侵权的初步证据和服务类型采取必要措施；未及时采取必要措施的，对损害的扩大部分与该网络用户承担连带责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('zhuangxiu-hetong', '《民法典》第 770 条',
     '承揽合同是承揽人按照定作人的要求完成工作，交付工作成果，定作人支付报酬的合同。承揽包括加工、定作、修理、复制、测试、检验等工作。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 1),
    ('zhuangxiu-hetong', '《民法典》第 781 条',
     '承揽人交付的工作成果不符合质量要求的，定作人可以合理选择请求承揽人承担修理、重作、减少报酬、赔偿损失等违约责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2),
    ('zhuangxiu-hetong', '《消费者权益保护法》第 8 条',
     '消费者享有知悉其购买、使用的商品或者接受的服务的真实情况的权利。消费者有权根据商品或者服务的不同情况，要求经营者提供商品的价格、产地、生产者、用途、性能、规格、等级、主要成份、生产日期、有效期限、检验合格证明、使用方法说明书、售后服务，或者服务的内容、规格、费用等有关情况。',
     'http://npc.gov.cn/zgrdw/npc/xinwen/2013-10/26/content_1811773.htm', 3),
    ('shenfenzheng-bei-maoyong', '《居民身份证法》第 17 条',
     '有下列行为之一的，由公安机关处二百元以上一千元以下罚款，或者处十日以下拘留，有违法所得的，没收违法所得：（一）冒用他人居民身份证或者使用骗领的居民身份证的；（二）购买、出售、使用伪造、变造的居民身份证的。伪造、变造的居民身份证和骗领的居民身份证，由公安机关予以收缴。',
     'https://www.gov.cn/gongbao/content/2003/content_62254.htm', 1),
    ('shenfenzheng-bei-maoyong', '《民法典》第 1165 条',
     '行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。',
     'https://www.12371.cn/2020/06/01/ARTI1591021670041266.shtml', 2);

INSERT INTO laws (card_slug, name, text, source_url, sort_order) VALUES
    ('shenfenzheng-bei-maoyong', '《个人信息保护法》第 69 条',
     '处理个人信息侵害个人信息权益造成损害，个人信息处理者不能证明自己没有过错的，应当承担损害赔偿等侵权责任。前款规定的损害赔偿责任按照个人因此受到的损失或者个人信息处理者因此获得的利益确定；个人因此受到的损失和个人信息处理者因此获得的利益难以确定的，根据实际情况确定赔偿数额。',
     'http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html', 3);
